 \|T_{j,m}(f,g)\|_{L^1}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}.
\end{equation}

\begin{equation}\label{l2c1}
 \|T_{j(x),m}(f,g)(x)\|_{L^1(dx)}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}.
\end{equation}

\begin{equation}\label{l2cp}
 \|T_{j(x),m}(f,g)(x)\|_{L^1(dx)}\lesssim_{\gamma,p} m\,\|f\|_p\,\|g\|_{p'}.
\end{equation}

\begin{equation}\label{l2cpp}
 \|T_{m}(f,g)\|_{L^1}\lesssim_{\gamma,p} m\,\|f\|_p\,\|g\|_{p'}.
\end{equation}

\begin{equation}\label{CS}
\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|\right)^2\lesssim_{\gamma} \|h\|_{\infty}^2\,\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})|^2\,,
\end{equation}

\begin{equation}\label{Cf}
\left\|\,\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|f*\check{\phi}_{m+j}*\check{\psi}_{m,p_0,j}|^2\right)^{\frac{1}{2}}\right\|_{p}\lesssim_{\gamma,p} m^{\frac{2}{p'}-1}\, \|f\|_{p}\;,
\end{equation}

\begin{equation}\label{Tjm-pqr}
	\|T_{j,m}(f,g)\|_r\lesssim_{\gamma,p,q}(1+m^{1-\frac{2}{p}})\,2^{-\frac{m}{10}(1-\frac{1}{p*})}\,\|f\|_p\,\|g\|_q.
	\end{equation}

\begin{equation}
\big\|T_{j(x),m}(f,g)(x)\big\|_{L^r(dx)}\le_{\gamma,r} (1+m^{1-\frac{1}{r}})2^{-\frac{m}{20r}}\|f\|_{2r}\|g\|_{2r},
\end{equation}

\begin{equation}
	\|M_\Gamma(f,g)\|_{L^p}\lesssim_p \|f\|_p\,\|g\|_\infty.
	\end{equation}

\begin{equation}
	\|M_\Gamma(f,g)\|_{L^q}\lesssim_{\gamma,q} \|f\|_\infty\,\|g\|_q.
	\end{equation}

\begin{equation}
	\|M_\gamma(g)\|_{L^q}\lesssim_{\gamma,q} \|g\|_q.
	\end{equation}

\begin{equation}\label{gammak1t}
|\gamma(2^{k})|\approx_{\gamma} 2^{k}|\gamma'(t)|\approx_{\gamma}|\gamma(2^{k+1})|\,.
\end{equation}

Consequently, since \eqref{z-coefficients} implies the absolute convergence of the sum $$\sum_{n_1,n_2}|c_{n_1,n_2}|\,\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}\,\sum_{n_1,n_2}|c_{n_1,n_2}|\,,$$
one realizes that the boundedness of each of $T_{j,m}$ can be thought as equivalent with the corresponding boundedness of $B_{j,m}^{0,0}$. Therefore, for notational simplicity, we redenote $B_{j,m}$ as $B_{j,m}^{0,0}$ and set $T_{j,m}$ as the correspondent operator associated with the newly defined $B_{j,m}$.
\end{observation}

Given the observation above, we will only focus our attention on
\begin{equation}\label{nbjxm}
 B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x} e^{-i 2^m\eta R(\frac{\xi}{\eta})}\phi(\xi)\phi(\eta)d\xi d\eta\,,
\end{equation}
or equivalently, on the corresponding operator $T_{j,m}$ obtained from $B_{j,m}$ via \eqref{BTtr1} (and \eqref{BTtr2} respectively).

Finally, we record the following key relation:
\begin{equation}\label{bt}
\|B_{j,m}\|_{L^2\times L^2 \to L^1}=\|T_{j,m}\|_{L^2\times L^2 \to L^1}\:.
\end{equation}

$\newline$
\noindent\underline{\textsf{Philosophy of our proof}}
$\newline$

\emph{Inspired by \cite{lie2015triangle}, our intention is to show that even in the variable case, the operator
$$T_{j(x),m}\:\:(\textrm{or equivalently}\:\:B_{j(x),m})\,$$
obeys similar decay bounds with $T_{j,m}$ which can be extracted from the corresponding bounds for the $j(x)=j$ constant case. In other words, one can identify a unified approach that deals simultaneously with both the bilinear Hilbert transform and the maximal operator along non-flat curves.}

Applying now Remark 2, for $j(x)=j$, one can identify $M_{j,m}^{H\Delta}(f,g)$ with the analogue $H_{j,m}^{H\Delta}(f,g)$ and thus use the key estimate obtained in \cite[Theorem 3]{lie2015boundedness} to get that there exists $\epsilon\in(0,1)$ such that, for any $j\in \mathbb{Z}$ and $m\in\mathbb{N}$, one has
\begin{equation}\label{l2cs}
 \|M^{H\Delta}_{j,m}(f,g)\|_{L^1}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}.

Thus, with a slight notational abuse, we will assume from now on that
\begin{equation}\label{discretizationc}
M_{\Gamma}(f,g)(x)=\sup\limits_{{j\in\mathbb{Z}}\atop{|j|>j_0}}\frac{1}{2^{j+1}}\int\limits_{2^j\le|t|\le2^{j+1}} f(x-t)\,g(x+\gamma(t))\,dt.
\end{equation}

Thus, putting together \eqref{lowTaylor} and \eqref{operator_low_freq} and recalling \eqref{notation22}, we have
\begin{align}
\mathcal{M}_\Gamma^L(f,g)(x)&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \Big(\int_\mathbb{R} \hat{f}(\xi)\tilde\psi_k\Big(\frac{\xi}{2^{j(x)}}\Big)e^{i\xi x}d\xi\Big) \Big(\int_\mathbb{R} \hat{g}(\eta)\tilde\psi_l\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big) e^{i\eta x}d\eta\Big)\nonumber\\
&\approx\sum_{k,l\ge0} \frac{(-1)^k }{k!\,l\,!}C_{k,l} \Big(f*\Big\{\frac{1}{2^{-j(x)}}\check{\psi}^{(k)}\Big(\frac{\cdot}{2^{-j(x)}}\Big)\Big\}\Big)(x)\label{low_frequency}\\
&\hspace{2cm}\times \Big(g*\Big\{\frac{1}{2^{-j(x)}\gamma'(2^{-j(x)})}\check{\psi}^{(l)} \Big(\frac{\cdot}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)\Big\}\Big)(x).\nonumber
\end{align}

Consequently, since \eqref{z-coefficients} implies the absolute convergence of the sum $$\sum_{n_1,n_2}|c_{n_1,n_2}|\,\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}\,\sum_{n_1,n_2}|c_{n_1,n_2}|\,,$$
one realizes that the boundedness of each of $T_{j,m}$ can be thought as equivalent with the corresponding boundedness of $B_{j,m}^{0,0}$. Therefore, for notational simplicity, we redenote $B_{j,m}$ as $B_{j,m}^{0,0}$ and set $T_{j,m}$ as the correspondent operator associated with the newly defined $B_{j,m}$.
\end{observation}

Thus, applying Cauchy-Schwarz inequality, we get
\begin{equation}\label{CS}
\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|\right)^2\lesssim_{\gamma} \|h\|_{\infty}^2\,\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})|^2\,,
\end{equation}
from which we deduce that
\begin{equation}\label{L}
|\ll_{m}^{+}(f,g,h)|\lesssim_{\gamma}  \|f\|_{p}\, \|h\|_{\infty}\,\left\|\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|g*\check{\phi}_{j,p_0}|^2\right)^{\frac{1}{2}}\right\|_{p'}\:.
\end{equation}

Thus, Proposition \ref{Tjmb} follows from the Proposition \ref{DeltaM} after applying real interpolation.
\end{proof}
\medskip

Hence, applying the classical results on the Hardy-Littlewood maximal operator we get
\begin{theorem}\label{ginfty}
	For any $1<p\le \infty$, one has
	\begin{equation}
	\|M_\Gamma(f,g)\|_{L^p}\lesssim_p \|f\|_p\,\|g\|_\infty.
	\end{equation}
\end{theorem}
$\smallskip$

Thus, Theorem \ref{finfty} follows from the result below
\begin{theorem}\label{Mgamma}
	For any $1<q\le \infty$, one has
	\begin{equation}
	\|M_\gamma(g)\|_{L^q}\lesssim_{\gamma,q} \|g\|_q.
	\end{equation}
\end{theorem}

Thus, from the classical theory, we get that for any $\alpha>0$ the following holds:
\begin{align*}
|\{x\in\mathbb{R}:M_\Gamma(f,g)(x)>\alpha\}|\lesssim \frac{1}{\alpha}\|f\|_1 \|g\|_\infty\:.
\end{align*}
\end{observation}

Main ideas; relevance
\label{MIR}



As already mentioned earlier, our approach of the maximal operator $M_{\G}$ is developed along a natural correspondence with the singular integral approach associated to the bilinear Hilbert transform $H_{\G}$. For the remaining part of this section, in order to make our reasoning transparent, we will keep our presentation at an \emph{informal level}.

The philosophy behind our approach relies on the following observation:

The bilinear Hilbert transform $H_{\G}$ can be written as
\begin{equation}\label{hilg}
H_{\G}(f,g)=\sum_{j\in\mathbb{Z}} H_j(f,g):=\sum_{j\in\mathbb{Z}} \int_{\mathbb{R}} f(x-t)\,g(x+\gamma(t)) \r_j(t)\,dt\,,
\end{equation}
where  here $\rho_j(t)=2^j\,\rho(2^j t)$ for a suitable $\rho\in C^\infty_0(\mathbb{R})$ with $\supp \rho \subseteq\{t\in\mathbb{R}|\frac{1}{4}<|t|<1\}$ and obeying the \emph{mean zero condition}
\begin{equation}\label{mzh}
\int_{\mathbb{R}}\rho(t)dt=0\,.
\end{equation}

In contrast with this, assuming from now on wlog that $f,\,g\geq 0$, the bilinear maximal function $M_{\G}$ can be expressed as
\begin{equation}\label{mg}
M_{\G}(f,g)=\sup_{j\in\mathbb{Z}} M_j(f,g):=\sup_{j\in\mathbb{Z}} \int_{\mathbb{R}} f(x-t)\,g(x+\gamma(t))\underline{\r}_j(t)\,dt\,,
\end{equation}
where  as before $\underline{\rho}_j(t)=2^j\,\underline{\rho}(2^j t)$ for a suitable $\underline{\rho}\in C^\infty_0(\mathbb{R})$ \emph{positive} with $\supp \underline{\rho} \subseteq\{t\in\mathbb{R}|\frac{1}{4}<|t|<1\}$ and obeying
\begin{equation}\label{nzh}
\int_{\mathbb{R}}\underline{\rho}(t)dt=1\,.
\end{equation}

\noindent \textsf{Remark 1} \emph{Thus, in a nutshell, one has
\begin{itemize}
\item $H_{\G}$ is a conditional $l^1$-sum of pieces $\{H_j\}_{j\in\mathbb{Z}}$ with the associated kernels $\{\r_j\}$ having mean zero;
\item $M_{\G}$ is an $l^{\infty}$-sum of pieces $\{M_j\}_{j\in\mathbb{Z}}$ with the associated kernels $\{\underline{\r}_j\}$ integrating to one.
\end{itemize}}

Once at this point, one can isolate the corresponding components $M_j$ (and $H_j$) and regard them as bilinear Fourier multiplier operators. In doing so, it becomes transparent that the phase oscillation in the integral definition of the multiplier will play a key role in the proof. Thus, following the strategy designed for $H_{\G}$ in \cite{lie2015boundedness}, we analyze the stationary points of the phase and decompose accordingly\footnote{Same type of decomposition holds for $H_j$.}
\begin{equation}\label{multiplierM}
 M_j=M_j^L+M_j^{H\not\Delta}+M_j^{H\Delta}\,,
\end{equation}
where
\begin{itemize}
\item $M_j^L$ is the $j-$low frequency component (essentially no phase oscillation);

\item $M_j^{H\not\Delta}$ is the $j-$high frequency component away from the stationary points region;

\item $M_j^{H\Delta}$ is the $j-$high frequency component along the stationary points region.
\end{itemize}

\noindent \textsf{Remark 2} \emph{As it turns out, only the first components $M_j^L$ and its Hilbert analogue $H_j^L$ are sensitive to the existent distinction
between \eqref{nzh} and \eqref{mzh}. Consequently, for the last two components one will be able to identify $M_j^{H\not\Delta}$ and $M_j^{H\Delta}$ with their analogue $H_j^{H\not\Delta}$ and $H_j^{H\Delta}$, respectively.}

From here on, the strategy follows the dichotomy present in \cite{lie2015boundedness}, \cite{lie2015triangle} and \cite{lie2019unifiedap}:

\begin{itemize}
\item the control over the low frequency component $\mathcal{M}^L_\Gamma:=\sup_j |M_j^L|$ is obtained via Taylor series expansions exploiting the lack of oscillation on the multiplier side; indeed, Theorem \ref{low_frequency_theorem} states that\footnote{Here $M$ stands for the standard Hardy-Littlewood maximal function.}
\begin{equation}\label{lf}
 |\mathcal{M}_\Gamma^L(f,g)(x)|\lesssim_\gamma Mf(x)Mg(x).
\end{equation}

\item the bounds for the high frequency component away from the stationary points region $\mathcal{M}^{H\not\Delta}_\Gamma:=\sup_{j} |M_j^{H\not\Delta}|$ rely on a further discretization combined with (non)-stationary principle in disguise - essentially a careful integration by parts procedure - and a novel shifted square/maximal function argument. As a byproduct of the latter, each of the elementary building blocks in the decomposition of $\mathcal{M}^{H\not\Delta}_\Gamma$ will be pointwise bounded by a product of shifted maximal functions (multiplied by a suitable decaying factor) thus mirroring \eqref{lf} (see relation \eqref{mvst}). The superposition of these pointwise estimates will provide us with the global control over $\mathcal{M}^{H\not\Delta}_\Gamma$.
     This is the content of Theorem \ref{far_theorem}.

\item the high frequency component along the stationary points region defined as $\mathcal{M}^{H\Delta}_\Gamma:=\sup_{j}| M_j^{H\Delta}|$ is of course the main term of our operator. After the linearization of the supremum, one decomposes the main term as
 \begin{equation}\label{decm}
 M_{j(x)}^{H\Delta}(f,g)(x)=\sum_{m\in\mathbb{N}}  M_{j(x),m}^{H\Delta}(f,g)(x)\,,
\end{equation}
where each $M_{j(x),m}^{H\Delta}(f,g)(x)$ has the phase of the multiplier oscillating at height $\approx2^m$.

Applying now Remark 2, for $j(x)=j$, one can identify $M_{j,m}^{H\Delta}(f,g)$ with the analogue $H_{j,m}^{H\Delta}(f,g)$ and thus use the key estimate obtained in \cite[Theorem 3]{lie2015boundedness} to get that there exists $\epsilon\in(0,1)$ such that, for any $j\in \mathbb{Z}$ and $m\in\mathbb{N}$, one has
\begin{equation}\label{l2cs}
 \|M^{H\Delta}_{j,m}(f,g)\|_{L^1}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}.
\end{equation}

At this point hinted by Remark 1 and the approach in \cite{lie2015boundedness}, one makes the simple observation
\begin{equation}\label{l2css}
 \|M^{H\Delta}_{j(x),m}(f,g)(x)\|_{L^1(dx)}\leq \sum_{j} \|M^{H\Delta}_{j,m}(f,g)\|_{L^1}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}\,,
\end{equation}
where in the last line we used Cauchy-Schwarz and the almost orthogonality of the inputs along the sequence $\{M^{H\Delta}_{j,m}(f,g)\}_{j\in\mathbb{Z}}$. This takes care of the bound $L^2\times L^2 \to L^1$.

The complete boundedness range, stated in Theorem \ref{high_frequency_diagonal theorem} relies in part on the techniques developed in \cite{lie2015triangle} along with (shifted or generalized) square function arguments.
\end{itemize}


The above description is part of a more general, philosophical approach - see \cite{lie2019unifiedap} - of treating simultaneously and in a unitary fashion both the singular - here $H_{\Gamma}$ - and its maximal variant - here $M_{\G}$.

Finally, this paper is meant as a preface to the significantly more complex study in \cite{lvUA3}, in which, completing the unification of the three themes introduced in \cite{lie2019unifiedap}, we will develop a unified approach for the boundedness of $H_{\G}$ and $M_{\G}$ in the case in which $\Gamma=(t,-\gamma(x,t))$ - thus allowing an $x-$dependence of $\gamma$ - where here $\gamma$ is a suitable non-degenerate curve that is smooth and doubling in $t$ but only \emph{measurable} in $x$.

Low frequency term
\label{low_frequency-subsection}

As discussed in \cite{lie2019unifiedap}, the dichotomy between the singular integral behavior and its maximal version manifests precisely in the low frequency case: indeed, this is the only situation that requires the mean zero condition of the kernel $\frac{1}{t}$ in the bilinear Hilbert transform case which translates, after the standard discretization procedure, into a condition of the from \eqref{mzh} as opposed to \eqref{nzh} in the maximal case. Based on this, the bilinear Hilbert transform required similar techniques with those used to prove the Coifman-Meyer theorem in order to obtain the necessary bounds for the corresponding low frequency component (see \cite[Theorem 1]{lie2015boundedness}).

In the bilinear maximal function case, our function $\underline{\rho}$ only satisfies $\int\underline{\rho}(t)dt=1$ but the good news is that - recall Remark 1 in Section 1.3. -  we only need to control an $l^{\infty}(\mathbb{Z})$-sum/norm (in $j$) as opposed to a conditional $l^1(\mathbb{Z})$-sum in the bilinear Hilbert transform case.

With this being said, we have

\begin{theorem}\label{low_frequency_theorem}
Set
\begin{equation}\label{operator_low_freq}
 \mathcal{M}^L_\Gamma(f,g)(x):=\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)m_{j(x)}^L(\xi,\eta)e^{i\xi x}e^{i\eta x}d\xi d\eta.
\end{equation}
Then, the following holds
\begin{equation}\label{pointwise_maximal}
 |\mathcal{M}_\Gamma^L(f,g)(x)|\lesssim_\gamma Mf(x)Mg(x).
\end{equation}
Furthermore, for any $p, q$ and $r$ satisfying \eqref{exponents10} and \eqref{exponents20} we have
\begin{equation}\label{pointwise_maximal_bound}
 \|\mathcal{M}_\Gamma^L(f,g)\|_r\lesssim_{\gamma,p,q}\|f\|_p\|g\|_{q}.
\end{equation}
\end{theorem}


\begin{proof}
Fix $m,n \in\mathbb{Z}_-$. From the definition of $\phi$ we have that $\big|\frac{\xi}{2^{j(x)}}\big|, \big|\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\big|\lesssim 1$, and by property (3)  as part of the definition of $\mathcal{NF}$ in \cite{lie2015boundedness}, we have
\[
\sup\limits_{t\in\supp\underline{\rho}}\Big|\eta\gamma\Big(\frac{t}{2^{j(x)}} \Big)\Big|<C_\gamma,
\]
where $C_\gamma$ is a positive constant that is allowed to change from line to line.

Recalling now \eqref{M_multiplierr} - \eqref{mjmn}, we develop the phase in \eqref{phmultiplier} in a Taylor series
\begin{align}
 m_{j(x),m,n}(\xi,\eta)&=\Bigg(\int_\mathbb{R} \sum_{k\in\mathbb{N}} \frac{(-i\frac{\xi}{2^{j(x)}}t)^k}{k!}\sum_{l\in\mathbb{N}}\frac{(i\eta\gamma(\frac{t}{2^{j(x)}}))^l}{l\,!}\underline{\rho}(t)dt\Bigg)\phi\Big(\frac{\xi}{2^{m+j(x)}} \Big)\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big)\nonumber\\

&=\sum_{k,l\ge0}\frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l}
\Big(\frac{\xi}{2^{j(x)}}\Big)^k\phi\Big(\frac{\xi}{2^{m+j(x)}}\Big) \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big)^l\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big),\label{taylor-series}
\end{align}
where
\[
 C_{k,l}=C_{j(x),k,l}:=\int_\mathbb{R} t^k\Big(\frac{\gamma(2^{-j(x)}t)}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)^l \underline{\rho}(t)dt.
\]
Since
\begin{equation}\label{constcont}
 |C_{k,l}|\lesssim C_\gamma^{k+l}
\end{equation}
uniformly in $x$, the sum \eqref{taylor-series} converges absolutely.

Set now
\begin{equation}\label{psi}
\psi(x):=\sum_{m<0}\phi(\frac{x}{2^m})\,,
\end{equation}
and notice that $\psi\in\mathcal{S}(\mathbb{R})$ since $\psi=1-\sum_{m\ge0}\phi_m.$

Inserting \eqref{taylor-series} in \eqref{low_freq} and recalling \eqref{notation21}, we have
\begin{align}
 m^L_{j(x)}(\xi,\eta)&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \Big(\frac{\xi}{2^{j(x)}}\Big)^k\psi\Big(\frac{\xi}{2^{j(x)}}\Big) \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big)^l
\psi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big),\\
&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \,\tilde\psi_k\Big(\frac{\xi}{2^{j(x)}}\Big) \tilde\psi_l\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big).\label{lowTaylor}
\end{align}



Thus, putting together \eqref{lowTaylor} and \eqref{operator_low_freq} and recalling \eqref{notation22}, we have
\begin{align}
\mathcal{M}_\Gamma^L(f,g)(x)&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \Big(\int_\mathbb{R} \hat{f}(\xi)\tilde\psi_k\Big(\frac{\xi}{2^{j(x)}}\Big)e^{i\xi x}d\xi\Big) \Big(\int_\mathbb{R} \hat{g}(\eta)\tilde\psi_l\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big) e^{i\eta x}d\eta\Big)\nonumber\\
&\approx\sum_{k,l\ge0} \frac{(-1)^k }{k!\,l\,!}C_{k,l} \Big(f*\Big\{\frac{1}{2^{-j(x)}}\check{\psi}^{(k)}\Big(\frac{\cdot}{2^{-j(x)}}\Big)\Big\}\Big)(x)\label{low_frequency}\\
&\hspace{2cm}\times \Big(g*\Big\{\frac{1}{2^{-j(x)}\gamma'(2^{-j(x)})}\check{\psi}^{(l)} \Big(\frac{\cdot}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)\Big\}\Big)(x).\nonumber
\end{align}

We can construct the function $\phi$ such that for every $k\in\mathbb{N}$, the function $\check{\psi}^{(k)}$ has an integrable radially decreasing majorant $\Phi_k$ with $\|\Phi_k\|_1\lesssim C^k$ for some constant $C>0$. Thus, using a classical result in \cite{stein1993harmonic}, one has
\begin{align}
\Big|\Big(f*\Big\{\frac{1}{2^{-j(x)}}\check{\psi}^{(k)}\Big(\frac{\cdot}{2^{-j(x)}}\Big)\Big\}\Big)(x)\Big|&\le \sup_{t>0} \Big|\Big(f*\Big\{\frac{1}{t}\check{\psi}^{(k)}\Big(\frac{\cdot}{t}\Big)\Big\}\Big)(x)\Big|\nonumber\\
&\le \|\Phi_k\|_1 Mf(x)\nonumber\\
&\lesssim C^k Mf(x).\label{Mf}
\end{align}

Analogously,
\begin{equation}\label{Mg}
\Big|\Big(g*\Big\{\frac{1}{2^{-j(x)}\gamma'(2^{-j(x)})}\check{\psi}^{(l)} \Big(\frac{\cdot}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)\Big\}\Big)(x)\Big|\lesssim C^l Mg(x).
\end{equation}
Putting together \eqref{low_frequency}, \eqref{Mf} and \eqref{Mg} we have
\begin{align*}
|\mathcal{M}_\Gamma^L(f,g)(x)|&\lesssim \sum\limits_{k,l\ge0}\frac{1}{k!\,l\,!}|C_{k,l}|C^{k+l}Mf(x)Mg(x)\\
&\lesssim Mf(x)Mg(x)\sum\limits_{k,l\ge0}\frac{1}{k!\,l\,!}C_\gamma^{k+l} C^{k+l}\\
&\lesssim_\gamma Mf(x)Mg(x),\numberthis\label{pointwise_result}
\end{align*}
where here we used \eqref{constcont}.

Therefore, \eqref{pointwise_maximal} holds.

Taking now $p,\, q,\, r$ satisfying \eqref{exponents10} and \eqref{exponents20}, H\"older’s inequality and the standard $L^p$ strong type estimate for the classical Hardy-Littlewood maximal function imply
 \begin{align*}
\|\mathcal{M}_\Gamma^L(f,g)\|_r&\lesssim_\gamma\|Mf Mg\|_r\lesssim_{p,q} \|Mf\|_p\|Mg\|_q\lesssim_{p,q} \|f\|_p \|g\|_q,
 \end{align*}
which concludes our proof.
\end{proof}

High frequency term far from diagonal
In this section we discuss the second (off-diagonal) term in our decomposition of $m_{j(x)}$, that is, $m_{j(x)}^{H\not\Delta}$.

Our main focus, will be to prove the following

\begin{theorem}\label{far_theorem}
 Set
 \begin{equation}\label{operator_far}
 \mathcal{M}^{H\not\Delta}(f,g)(x):=\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)m_{j(x)}^{H\not\Delta}(\xi,\eta)e^{i\xi x}e^{i\eta
x}d\xi d\eta,
 \end{equation}
 and for $(m,n)\in\mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)$ let
  \begin{equation}\label{operator_far}
 \mathcal{M}^{H\not\Delta}_{m,n}(f,g)(x):=\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)m_{j(x),m,n}(\xi,\eta)e^{i\xi x}e^{i\eta
 	x}d\xi d\eta.
 \end{equation}
 Then, for any $p, q, r$ satisfying \eqref{exponents10} and  \eqref{exponents20}, the following holds
 \begin{itemize}
 	\item If $(m,n)\in\mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)$ then, recalling \eqref{shif_maxM} and \eqref{shif_maxgamaM}, one has the pointwise estimate
  \begin{equation}\label{mvst}
|\mathcal{M}^{H\not\Delta}_{m,n}(f,g)(x)|\lesssim \frac{1}{2^{\max\{m,n\}}}\,\int\limits_{\{\frac{1}{4} <|t|<1 \}} M^{(2^m t)}f(x)\,M^{(2^n)}_{\gamma_t} g(x)\,dt\:\:\:\:\:\:\:\:\forall\:x\in\mathbb{R}\,,
\end{equation}
which further implies
 	\begin{equation}
 	\|\mathcal{M}^{H\not\Delta}_{m,n}(f,g)\|_r\lesssim_{\gamma,p,q}\frac{1}{2^{\max\{m,n\}}}(m_++10) (n_++10)\|f\|_p\|g\|_{q}\,.\label{far_bound}
 	\end{equation}

\item Deduce thus that the global component obeys
 	\begin{equation}
 	\|\mathcal{M}_\Gamma^{H\not\Delta}(f,g)\|_r\lesssim_{\gamma,p,q}\|f\|_p\|g\|_q.\label{far_thm_bound}
 	\end{equation}
 \end{itemize}
\end{theorem}

We first state two lemmas which will be used in the proof of the above statement.

The first lemma contains two items: point i) represents Lemma 4.8 proved in \cite{lie2015triangle} and can be found in the math literature under various modified forms - see \textit{e.g.} \cite{MS} and \cite{stein1993harmonic}. The second point ii) can be proved with similar techniques to those used for i) and relies in a key fashion on the properties of the class of curves $\mathcal{NF}$. The second lemma mirrors the first one and addresses the maximal function analogue. The case of $M^{(2^n t)}$ was also referred to and proved within Proposition 42 in \cite{lie2019unifiedap}.

\begin{lemma}\label{shifted_square_funct}
Let $\frac{1}{4} <|t|<1$, $\v\in C^\infty_0$ with $\v(0)=0$, $n\in\mathbb{Z} $ and $\gamma\in\mathcal{NF}$.

\noindent i) Recall the definition of $S_t^{\v}$ given by \eqref{shif_max} in the Notation section.

Then, for any $1<p<\infty$, one has -- uniformly in $t$ -- that
\[
  \|S_{2^n t}^{\v}f\|_p\lesssim_{\v,p} (1+n_{+})^{\frac{2}{p^*}-1}\|f\|_p.
\]

\noindent ii) Similarly, if $S_{n,\gamma_t}^{\v}$ stands for the shifted square functions defined in \eqref{shif_maxgama} then, for any $1<p<\infty$, one has -- uniformly in $t$ -- that
\begin{equation}\label{sup_displaced}
\|S_{n,\gamma_t}^{\v}f\|_p\lesssim_{\gamma,\v,p}(1+n_{+})^{\frac{2}{p^*}-1}\|f\|_p\:.
 \end{equation}
\end{lemma}



\begin{lemma}\label{shifted_max_funct}
With the same assumptions as above, and appealing to \eqref{shif_maxM} and \eqref{shif_maxgamaM} in the Notation section we have
that
\begin{equation}\label{sup_displaced}
\|M^{(2^n t)}f\|_p,\:\|M^{(2^n)}_{\gamma_t}f\|_p\lesssim_{\gamma,\v,p}(1+n_{+})^{\frac{1}{p}}\|f\|_p\:,
 \end{equation}
holds uniformly in $t$ and for all $1<p\leq\infty$.
\end{lemma}

With these we are now ready to present

\begin{proof}[Proof of Theorem \ref{far_theorem}]

Fix a pair $(m,n)\in\mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)$. As in the proof of \cite[Claim 1]{lie2015boundedness}, integrating by parts, we write
\[
 m_{j(x),m,n}=A_{j(x),m,n}(\xi,\eta)+B_{j(x),m,n}(\xi,\eta),
\]
where
\begin{equation}
 A_{j(x),m,n}(\xi,\eta):=\Big(\int_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t} e^{i\eta\gamma(\frac{t}{2^{j(x)}})} \frac{i\
\underline{\rho}'(t)}{-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}dt\Big)
\phi\Big(\frac{\xi}{2^{m+j(x)}} \Big) \phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big),
\end{equation}
and
\begin{equation}
 B_{j(x),m,n}(\xi,\eta):= \Big(\int\limits_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t}e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)}
\frac{-i\frac{\eta}{2^{2j(x)}}\gamma''\big(\frac{t}{2^{j(x)}}\big)} {\Big({-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}\Big)^2} \underline{\rho}(t)dt\Big)
\phi\Big(\frac{\xi}{2^{m+j(x)}}\Big)\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big).
\end{equation}



\item \textsf{Case 1}: $m-n\ge C_\gamma>>1$
$\newline$

By (3) in the definition of $\mathcal{NF}$, we have that
\[
\tfrac{1}{-\tfrac{\xi}{2^{j(x)}}+\tfrac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}=-\tfrac{1}{2^m}\frac{1}{\frac{\xi}{2^{m+j(x)}}} \sum_{l\in\mathbb{N}} \tfrac{1}{2^{l(m-n)}}\Bigg(\frac{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}{\frac
{\xi}{2^{m+j(x)}}}\Bigg)^l (Q'(t)+Q'_{j(x)}(t))^l.
\]
Set
\[
 A_{j(x),m,n}=\sum_{l\in\mathbb{N}} A_{j(x),m,n,l},
\]
with
\begin{align*}
 A_{j(x),m,n,l}(\xi,\eta)&=-\frac{1}{2^m}\frac{1}{2^{l(m-n)}} \left(\int_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t} e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)} i\,\underline{\rho}'(t) (Q'(t)+Q_{j(x)}(t))^l dt\right)\\
&\hspace{2.5cm}\times
\tilde{\phi}_{-l-1}\Big(\frac{\xi}{2^{m+j(x)}}\Big)\tilde{\phi}_{l} \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big)
\end{align*}
where here $\tilde{\phi}_{l}$, $l\in\mathbb{Z}$, is smooth, compactly supported away from the origin, and obeying
\[
\|\tilde{\phi}_{l}\|_{C^\beta}\lesssim\beta!\,(|l|+\b)^{\b}\,
C^{|l|+\b}
\]
for $\b\in\mathbb{N}$ and some fixed $C>0$.

We recall now the fact that, from the properties of $\gamma\in\mathcal{NF}$ one has that $\|Q_j\|_{C^N}\le a_j$ with $a_j\to 0$ as
$j\to\infty$ and thus, since $|j(x)|\geq j_0$, one can choose $j_0\in\mathbb{N}$ large enough so that $\|Q_{j(x)}\|_{C^N}\leq \|Q\|_{C^N}\:\:\textrm{a.e.}\:x\in\mathbb{R}$.

 Defining the operator $\Lambda^A$ as
\[
\Lambda^A_{m,n,l}(f,g)(x):=\int_\mathbb{R}\int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta) A_{j(x),m,n,l}(\xi,\eta)e^{i\xi x}e^{i\eta x}d\xi d \eta,
\]
we have
\begin{align}
|\Lambda^A_{m,n,l}(f,g)(x)|&=\Big|\frac{1}{2^m}\frac{1}{2^{l(m-n)}} \int_\mathbb{R} (f*\check{\tilde{\phi}}_{-l-1,m+j(x)})\big(x-\frac{2^mt}{2^{m+j(x)}}\big)\label{sqv}\\
&\hspace{.1cm}\times \big(g*\big\{\tilde{\phi}_l\big(\tfrac{2^{-j(x)}\gamma'(2^{-j(x)})}{2^n}\,\cdot\big)\big\} \check{\phantom{1}}\big)\big(x+\gamma(2^{-j(x)}t)\big) \,\underline{\rho}'(t)\,(Q'(t)+Q'_{j(x)}(t))^l\, dt\Big|\nonumber\\
&\lesssim \frac{1}{2^m}\Big(\frac{2\|Q'\|_\infty}{2^{m-n}}\Big)^l \int\limits_{\{t\in\mathbb{R}:\frac{1}{4} <|t|<1 \}}
\sup_{j\in\mathbb{Z}}\Big|(f*\check{\tilde{\phi}}_{-l-1,j})\big(x-\frac{2^mt}{2^j}\big)\Big| \nonumber\\
&\hspace{.5cm}\times
\sup_{j\in\mathbb{Z}}\Big|\big(g*\big\{\frac{1}{\tfrac{2^{-j}\gamma'(2^{-j})}{2^n}} \check{\tilde{\phi}}_l (\frac{\cdot}{\tfrac{2^{-j}\gamma'(2^{-j})}{2^n}})\big\}\big) (x+\gamma(2^{-j}t))\,\Big|\,dt\nonumber\:.
\end{align}
Once at this point one can proceed in two ways:
\begin{itemize}
\item the simplest route is to apply the estimate
\begin{equation}\label{mv}
|\Lambda^A_{m,n,l}(f,g)(x)|\lesssim \frac{1}{2^m}\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l \int\limits_{\{\frac{1}{4} <|t|<1 \}} M^{(2^m t)}f(x)\,M^{(2^n)}_{\gamma_t} g(x)\,dt\,.
\end{equation}
\item alternatively, one can appeal to a shifted square function argument, and write
\begin{equation}\label{sv}
|\Lambda^A_{m,n,l}(f,g)(x)|\lesssim \frac{1}{2^m}\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l \left(\int\limits_{\{\frac{1}{4} <|t|<1 \}} S_{2^mt}^{\tilde{\phi}_{-l-1}}f(x)\,S_{n,\gamma_t}^{\tilde{\phi}_l}g(x)\,dt\right)\,.
\end{equation}
\end{itemize}




Let $\Lambda^A_{m,n}:=\sum_{l\in\mathbb{N}} \Lambda^A_{m,n,l}$. Using now Fubini, H\"older, Lemma \ref{shifted_max_funct} and \eqref{mv} (or alternatively, Lemma \ref{shifted_square_funct} and \eqref{sv}), one deduces
\begin{equation}\label{A1}
\|\Lambda^A_{m,n}(f,g)\|_r\lesssim_{\gamma,p,q}\frac{1}{2^m}(m_++10)(n_{+}+10)\,\|f\|_p\,\|g\|_q\:.
\end{equation}



Similarly, one gets the analogues of \eqref{A1} for the multiplier $B_{j,m,n}$, where in this latter case one uses that
$\frac{1}{2^{2j}}\gamma''(2^{-j}t)=2^{-j}\gamma'(2^{-j})(Q''(t)+Q_j''(t))\,.$
$\newline$


\item \textsf{Case 2}: $n-m>C_\gamma>>1$
$\newline$

As we did in Case 1, we write
\[
\frac{1}{-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}
	\gamma'(\frac{t}{2^{j(x)}})}
=\frac{1}{2^{n}}\frac{1}{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}
\sum_{l\in\mathbb{N}}\frac{1}{2^{l(n-m)}} \Bigg(\frac{\frac{\xi}{2^{m+j(x)}}}
{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}\Bigg)^l\frac{1}{(Q'(t)+Q'_{j(x)}
	(t))^{l+1}}.
\]
Write
\[
\tilde{A}_{j(x),m,n}=\sum_{l\in\mathbb{N}}\tilde{A}_{j(x),m,n,l},
\]
where
\begin{align*}
\tilde{A}_{j(x),m,n,l}(\xi,\eta)&=\frac{1}{2^{n}}\frac{1}{2^{l(n-m)}}
\left(\int_\mathbb{R}
e^{-i\frac{\xi}{2^{j(x)}}t}e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)}i
\frac{\underline{\rho}'(t)}{(Q'(t)+Q'_{j(x)}(t))^{l+1}}dt\right) \\
&\hspace{2cm}\times
\tilde{\phi}_{l}\left(\frac{\xi}{2^{m+j(x)}}\right)\,\tilde{\phi}_{-l-1}\left(\frac{
	\gamma'(2^{-j(x)})\,\eta}{2^{n+j(x)}}\right).
\end{align*}

Letting $\Lambda^{\tilde{A}}_{m,n,l}$ be the operator with symbol
$\tilde{A}_{j(\cdot),m,n,l}$ one proceeds as before in order to get
\begin{equation*}
|\Lambda^{\tilde{A}}_{m,n,l}(f,g)(x)|\lesssim
\frac{1}{2^n}\,\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l\,\left(\int\limits_{\{\frac{1}{4} <|t|<1 \}} M^{(2^m t)}f(x)\,M^{(2^n)}_{\gamma_t} g(x)\,dt\right) \,,
\end{equation*}
and respectively
\begin{equation}\label{A2}
\|\Lambda^{\tilde{A}}_{m,n}(f,g)\|_r\lesssim_{\gamma,p,q} \frac{1}{2^n}(m_++10)\,(n_{+}+10)\,
\|f\|_p\,\|g\|_{q}.
\end{equation}
Again, a similar reasoning applies to the multiplier $\tilde{B}_{j(\cdot),m,n}$.

Putting together all of the above, one concludes
\begin{align*}
\|M_\Gamma^{H\not\Delta}(f,g)\|_r &\lesssim_{\gamma,p,q}
\sum_{\substack{(m,n)\in \mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)\\ m-n\geq C_{\gamma}}}
\frac{1}{2^m}(m_++10)\,(n_{+}+10)\,\|f\|_p\,\|g\|_q\\
&\hspace{1cm} +
\sum_{\substack{(m,n)\in \mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)\\ n-m\geq C_{\gamma}}}
\frac{1}{2^n}(m_++10)\,(n_{+}+10)\,\|f\|_p\,\|g\|_q\\
&\lesssim_{\gamma,p,q} \|f\|_p\,\|g\|_q.
\end{align*}
\end{proof}

High frequency term close to diagonal
In this section we consider the last and most relevant component of $m_{j(x)}$, that is, the term $m_{j(x)}^{H\Delta}$.

Our goal for the remaining part of the paper will be to prove the following

\begin{theorem}\label{high_frequency_diagonal theorem}
Set
 \begin{equation}\label{operator_close}
 \mathcal{M}^{H\Delta}(f,g)(x):=\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)m_{j(x)}^{H\Delta}(\xi,\eta)e^{i\xi x}e^{i\eta
x}d\xi d\eta.
 \end{equation}
Then for any $p,\,q,\, r$ satisfying \eqref{exponents10} and \eqref{exponents20} we have
\begin{equation}\label{close_bound}
 \|\mathcal{M}_\Gamma^{H\Delta}(f,g)\|_r\lesssim_{\gamma,p,q}\|f\|_p\|g\|_{q}.
\end{equation}
\end{theorem}


In this subsection we will describe the strategy of reducing our Theorem \ref{high_frequency_diagonal theorem} to two intermediate results.

We start by noticing that in \eqref{high-close} it is enough to only consider the case $m=n.$ Also, wlog we assume that our $t$-integration encoded in the expression of $m_{j(x)}^{H\Delta}$ is performed over $\mathbb{R}_+$.

\begin{observation}\label{identif} Recalling Remark 2 in Section \ref{MIR}, since the mean zero condition in \eqref{mzh} plays no role in the regions where the phase of the multiplier is highly oscillatory, we are justified from now on to identify our operators $T_{j,m}$ and $B_{j,m}$ introduced below with the corresponding ones defined in \cite{lie2015boundedness}. Consequently, one can transfer with no modifications the theorems regarding $T_{j,m}$ and $B_{j,m}$ in \cite{lie2015boundedness} to our current setting.
\end{observation}

Using now the notation from \cite[Section 3]{lie2015triangle} and after some elaborate technicalities, one can prove that the study of the operator with multiplier $m_{j(x)}^{H\Delta}$ can be reduced to the study of the bilinear operator $T(f,g)$ defined by
\begin{equation}\label{T}
 T(f,g)(x):=\sum_{m\in\mathbb{N}}T_{j(x),m}(f,g)(x)\,.
\end{equation}
Here, for each $j\in\mathbb{Z}$ and $m\in\mathbb{N}$, we define
\begin{equation}\label{Tjm}
T_{j,m}(f,g)(x):=\int_\mathbb{R}\int_\mathbb{R}\hat{f}(\xi)\hat{g}(\eta)v_{j,m}(\xi,\eta)e^{i\xi x}e^{i\eta x} d\xi d\eta
\end{equation}
and
\begin{equation}\label{vjm}
v_{j,m}(\xi,\eta):=2^{-\frac{m}{2}}e^{i\,\varphi_{\xi,\eta}(t_c)} \zeta\Bigg(\frac{\gamma'(2^{-j})\eta}{2^{m+j}},
\frac{\frac{\xi}{2^{m+j}}}{\frac{\gamma'(2^{-j})\eta}{2^{m+j}}}\Bigg) \phi\Big(\frac{\xi}{2^{m+j}}\Big) \phi\Big(\frac{\gamma(2^{-j})\eta}{2^{m+j}}\Big)
\end{equation}
where we have
\begin{itemize}
 \item the phase of the multiplier - recall \eqref{phmultiplier} - is defined as
 \begin{equation}
\varphi_{\xi,\eta}(t):=-\frac{\xi}{2^j}t+\eta\gamma\big(\frac{t}{2^j}\big).
 \end{equation}
 \item For $\xi,\eta$ fixed, $\varphi_{\xi,\eta}$ has a unique critical point $t_c=t_c(j,\xi,\eta) \in [2^{-k(\gamma)},2^{k(\gamma)}]$, where $k(\gamma)\in\mathbb{N}$ depends only on $\gamma$.
 \item $\zeta:[\frac{1}{10},10]\times[2^{-k(\gamma)},2^{k(\gamma)}]\to\mathbb{R}$ satisfies $\|\zeta\|_{N-3}\lesssim  1$ for some $N\ge7$.\footnote{The regularity index $N$ here can be lowered but we will not detail this fact here.}
\end{itemize}

Also, from the properties of the class $\mathcal{NF}$, wlog we can assume that
\begin{equation}\label{lim}
 \lim\limits_{\substack{t\to0\\ t\not=0}}\gamma'(t)=0\quad \text{ and } \quad \lim\limits_{t\to\infty}\gamma'(t)=\infty.
\end{equation}

Now it turns out that in formulas \eqref{Tjm} and \eqref{vjm} one can replace the function $\zeta$ by $1$. In order to clarify this point and make transparent the parallelism with the reasonings in \cite{lie2015boundedness}, we first need to recall some of the notations that we used in \cite{lie2015boundedness}. Thus, letting $\Psi_\eta(\xi)=-\varphi_{\xi,\eta}(t_c)$, we have




\begin{itemize}
 \item For $j>0$ one sets
\begin{equation}\label{BTtr1}
B_{j,m}(f(\cdot),g(\cdot))(x):=[\gamma'(2^{-j})]^\frac{1}{2}T_{j,m} \Big(f(2^{m+j}\cdot),g\Big(\frac{2^{m+j}}{\gamma'(2^{-j})} \cdot\Big)\Big)\Big(\frac{x\gamma'(2^{-j})}{2^{m+j}}\Big),
\end{equation}
that is
\[
B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i 2^m 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)}\zeta(\eta,\frac{\xi}{\eta})\phi(\xi)\phi(\eta)d\xi d\eta.
\]
 \item For $j\le 0$ one sets
\begin{equation}\label{BTtr2}
B_{j,m}(f(\cdot),g(\cdot))(x):=[\gamma'(2^{-j})]^{-\frac{1}{2}}T_{j,m} \Big(f(2^{m+j}\cdot),g\Big(\frac{2^{m+j}}{\gamma'(2^{-j})} \cdot\Big)\Big)\Big(\frac{x}{2^{m+j}}\Big),
\end{equation}
that is
\[
B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^{-\frac{1}{2}} \int_\mathbb{R} \int_\mathbb{R}
\hat{f}(\xi)\hat{g}(\eta)e^{i(\xi+\frac{\eta}{\gamma'(2^{-j})})x} e^{-i 2^m 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)}
\zeta(\eta,\frac{\xi}{\eta})\phi(\xi)\phi(\eta)d\xi d\eta.
\]
\end{itemize}
In what follows we will assume $j>0$, as the other case $j < 0$ can be treated in a similar way.

From the definition of $\gamma\in\mathcal{NF}$ we define for $x\in\mathbb{R}$
\[
 R(u):=\int_1^u r(s)ds \quad\text\quad R_{j}(u)=\int_1^u r_{j}(s)ds,
\]
then
\[
 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)=\eta R(\frac{\xi}{\eta})+\eta R_{j}(\frac{\xi}{\eta}).
\]
From the properties of $\gamma\in\mathcal{NF}$ we know that $\lim_{|j|\rightarrow\infty} \|R_j\|_{C^N}=0$. Thus, by properly choosing $j_0\in\mathbb{N}$ in \eqref{threshold} (based on the properties of $\gamma\in\mathcal{NF}$), one can assume wlog that one has the pointwise estimate $|R_j|\leq \frac{1}{C_{\gamma}}|R|$ for some large $C_{\gamma}>>1$. Consequently, $R_j$ behaves as an error term relative to $R$, and thus, for notational simplicity,  we will discard $R_j$ in what follows.


Thus, we have
\begin{equation}\label{bjxm}
B_{j,m}(f,g)(x):=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R}
\int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i 2^m \eta
R(\frac{\xi}{\eta})}\zeta(\eta,\frac{\xi}{\eta}
)\phi(\xi)\phi(\eta)d\xi d\eta.
\end{equation}


With these we are now ready to state the following

\begin{observation}
As in \cite[Section 5]{lie2015boundedness}, one can show that the function
$\zeta$ above can be replaced by the constant function $1$. This brings a series of simplifications especially when dealing later with the situation $p\not=2$. Instead of following the argument in  \cite[Section 5]{lie2015boundedness}, we present here a much simpler approach: the secret lies in changing the perspective and focusing on the function
\[
\varrho(\xi,\eta):=\zeta(\eta,\frac{\xi}{\eta})\,.
\]
Indeed, by doing this, one can perform a double Fourier series development on $\varrho$ and notice that the linear complex exponentials will preserve the curvature of the phase given by $2^m\eta R(\frac{\xi}{\eta})$; in contrast with this, in the original argument focusing on $\zeta(\eta,\frac{\xi}{\eta})$, after the double Fourier series argument one had to work extra in order to deal with expressions of the form $\{\frac{\xi}{\eta}n_2\}_{n_2\in\mathbb{Z}}$.

Returning now to the above definition of $ \varrho$ we notice that $\varrho:[\frac{2^{-k(\gamma)}}{10},10\cdot 2^{k(\gamma)}]
\times[\frac{1}{10},10] \to\mathbb{R}$ satisfies $\|\varrho\|_{C^{N-3}}\lesssim_\gamma
1$. This last property follows from the fact that both $\xi$
and $\eta$ are away from $0$.

We can now assume without loss of generality that $\varrho$ is compactly supported on $[2\pi,4\pi]\times[2\pi,4\pi]$. Regarding now $\varrho$ as a $2\pi$-periodic function on $\mathbb{R}^2$, we represent it as a multiple Fourier series:
\[
\varrho(\xi,\eta)=\sum_{n_1,n_2\in\mathbb{Z}}c_{n_1,n_2}e^{i n_1 \xi}e^{i n_2 \eta}.
\]

From the hypothesis that $\|\varrho\|_{C^{N-3}}\lesssim_\gamma 1$ with $N\geq 7$, we have
\begin{equation}\label{z-coefficients}
|c_{n_1,n_2}|\lesssim_\gamma \frac{1}{(1+|n_1|+|n_2|)^4}.
\end{equation}
Thus, for $j>0$, it follows that
\begin{equation}\label{B-Fourier}
B_{j,m}(f,g)(x)=\sum_{n_1,n_2\in\mathbb{Z}}c_{n_1,n_2}B_{j,m}^{n_1,n_2}(f,g)(x)
\end{equation}
with
\begin{equation}\label{BFourier1}
B_{j,m}^{n_1,n_2}(f,g)(x):=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2}
\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i
	2^m \eta R(\frac{\xi}{\eta})}e^{i\xi n_1}e^{i\eta n_2}\phi(\xi)\phi(\eta)d\xi d\eta.
\end{equation}
At this point we make the following simple observation: $\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}$ for any $n_1,\,n_2\in \mathbb{Z}$ since
the factors $e^{i\xi n_1}$ and $e^{i\eta n_2}$ can be absorbed into the functions $\hat f$ and $\hat g$ in \eqref{BFourier1} without changing their corresponding $L^2$-norms.

Consequently, since \eqref{z-coefficients} implies the absolute convergence of the sum $$\sum_{n_1,n_2}|c_{n_1,n_2}|\,\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}\,\sum_{n_1,n_2}|c_{n_1,n_2}|\,,$$
one realizes that the boundedness of each of $T_{j,m}$ can be thought as equivalent with the corresponding boundedness of $B_{j,m}^{0,0}$. Therefore, for notational simplicity, we redenote $B_{j,m}$ as $B_{j,m}^{0,0}$ and set $T_{j,m}$ as the correspondent operator associated with the newly defined $B_{j,m}$.
\end{observation}

Given the observation above, we will only focus our attention on
\begin{equation}\label{nbjxm}
 B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x} e^{-i 2^m\eta R(\frac{\xi}{\eta})}\phi(\xi)\phi(\eta)d\xi d\eta\,,
\end{equation}
or equivalently, on the corresponding operator $T_{j,m}$ obtained from $B_{j,m}$ via \eqref{BTtr1} (and \eqref{BTtr2} respectively).

Finally, we record the following key relation:
\begin{equation}\label{bt}
\|B_{j,m}\|_{L^2\times L^2 \to L^1}=\|T_{j,m}\|_{L^2\times L^2 \to L^1}\:.
\end{equation}

$\newline$
\noindent\underline{\textsf{Philosophy of our proof}}
$\newline$

\emph{Inspired by \cite{lie2015triangle}, our intention is to show that even in the variable case, the operator
$$T_{j(x),m}\:\:(\textrm{or equivalently}\:\:B_{j(x),m})\,$$
obeys similar decay bounds with $T_{j,m}$ which can be extracted from the corresponding bounds for the $j(x)=j$ constant case. In other words, one can identify a unified approach that deals simultaneously with both the bilinear Hilbert transform and the maximal operator along non-flat curves.}

\begin{figure}[h]
	\includegraphics[scale=.47]{triangle.png}
	\caption{\textbf{Maximal boundedness range for the Bilinear Maximal Function $M_\Gamma$.} Our Main Theorem states that our operator  $M_\Gamma:L^p(\mathbb{R})\times L^q(\mathbb{R})\to L^{r}(\mathbb{R})$ is bounded for all triples $(\frac{1}{p},\frac{1}{q},\frac{1}{r'})$ in the region $\overline{\text{int}(\triangle ABC)}\setminus (\{A\}\cup\{B\})$. This result is sharp.}
	\label{triangle_fig}
\end{figure}

$\newline$
\noindent\underline{\textsf{Main strategy}}
$\newline$

Recall now the definition of our main operator $T(f,g)$ in \eqref{T}. Our proof will be decomposed into two main parts each split in several stages - see Figure \ref{triangle_fig}:
$\medskip$
\begin{itemize}
 \item First part - \underline{boundedness properties of $T$ on $\text{int}(\triangle ABC)\cup (AB)$} - via $m-$decay bounds for $T_{j(x),m}$:
\begin{itemize}
\item in the first stage we provide $m-$decay bounds for $T_{j(x),m}$ on the edge $(AB)$;

\item in the second stage we provide $m-$decay bounds for $T_{j(x),m}$ on the edge $(CD)$;
\end{itemize}

Then our result holds in $\text{int}(\triangle ABC)$ by applying interpolation.
$\medskip$

\item Second part - \underline{boundedness properties of $T$ on $\partial(\triangle ABC)$}:

\begin{itemize}
\item for this situation, in the first stage we provide bounds on the edge $(AC]$;

\item in the second stage we provide bounds on the edge $(BC)$;

\item in the third stage we prove the unboundedness of our operator at the remaining vertices $\{A\}$ and $\{B\}$.
\end{itemize}
\end{itemize}

Bounds on the segment $(CD)$: $p=q=2r$ with $1<r<\infty$
$\newline$


The main result of this subsection is
\begin{theorem}\label{2r}
	Let $1\le r<\infty$. For $m\in\mathbb{N}$, the following holds
	\begin{equation}
	\|T_{j(x),m}(f,g)(x)\|_{L^r(dx)}\lesssim_{\gamma,r}(1+m^{1-\frac{1}{r}})\,2^{-\frac{m}{20r}}\,\|f\|_{2r}\,\|g\|_{2r}.
	\end{equation}
\end{theorem}




In order to prove our Theorem \ref{2r} we will need the following

\begin{proposition}\label{Tjmb}
	Let $p, q, r$ be as in \eqref{exponents10} and \eqref{exponents20}. Then for any $j, m\in\mathbb{Z}$, we have
	\begin{equation}\label{Tjm-pqr}
	\|T_{j,m}(f,g)\|_r\lesssim_{\gamma,p,q}(1+m^{1-\frac{2}{p}})\,2^{-\frac{m}{10}(1-\frac{1}{p*})}\,\|f\|_p\,\|g\|_q.
	\end{equation}
\end{proposition}

\begin{proof}
Using the notation from (\ref{Ljm}) and \cite{lie2015triangle}, we choose $h\in L^{r'}$ such that
\[
\Lambda_{j,m}(f,g,h)= \int_\mathbb{R} T_{j,m}(f,g)(x)h(x)dx.
\]
Therefore
\[
	|\Lambda_{j,m}(f,g,h)|\le 
	\int_\mathbb{R} |(f*\check{\phi}_{m+j})(x)\:|M\Bigg(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j, p_0})(\cdot) (h*\check{\phi}_{j, p_0})(\cdot)|\Bigg)(x)\,dx,
\]
and
\[
	|\Lambda_{j,m}(f,g,h)|\le 
	\int_\mathbb{R}\Bigg(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j, p_0})(x)(h*\check{\phi}_{j, p_0})(x)|^2\Bigg)^\frac{1}{2} \Bigg(\sum_{p_0=2^m}^{2^{m+1}}|(f*\check{\phi}_{m+j}*\check{\psi}_{m, p_0, j})(x)|^2\Bigg)^\frac{1}{2}dx.
\]

Hence, by following the second part of the proof of \cite[Proposition  4.2 ]{lie2015triangle} and \cite[Proposition 4.3 ]{lie2015triangle}, we deduce that the results in \cite{lie2015triangle} hold for $\Lambda_{j,m}$. In particular, the analogue of \cite[Theorem 3.3]{lie2015triangle} follows:

\begin{proposition}\label{DeltaM}
Let $1<p<\infty$. Then the following estimates hold
\begin{equation}
Edge\:(AC):\:\:\:\:\:\:\:\:|\Lambda_{j,m}(f,g,h)|\lesssim_{\gamma,p} (1+m^{1-\frac{2}{p}})2^{-\frac{m}{10}(1-\frac{1}{p*})}\|f\|_p\|g\|_\infty \|h\|_{p'},
\end{equation}
and
\begin{equation}
Edge\:(AB):\:\:\:\:\:\:\:\:|\Lambda_{j,m}(f,g,h)|\lesssim_{\gamma,p} (1+m^{1-\frac{2}{p}})2^{-\frac{m}{10}(1-\frac{1}{p*})} \|f\|_p\|g\|_{p'} \|h\|_\infty.
\end{equation}
\end{proposition}

Thus, Proposition \ref{Tjmb} follows from the Proposition \ref{DeltaM} after applying real interpolation.
\end{proof}
\medskip

We are now ready for the following:
\begin{proof}[Proof of Theorem \ref{2r}]
$\newline$

	As we did for the proof of \eqref{l2c2}, we write \eqref{Tjm-pqr} as
\begin{equation}
\|T_{j,m}(f,g)\|_r\lesssim_{\gamma}(1+m^{1-\frac{1}{r}})2^{-\frac{m}{20r}}\|f*\check{\phi}_{m+j}\|_{2r}\|g*\check{\phi}_{\gamma,m,j}\|_{2r},
\end{equation}
where here we used that $p=q=2r$ and that $(2r)^*=\frac{2r}{2r-1}$ since $r\ge 1$.

Since
\begin{equation*}
	|T_{j(x),m}(f,g)(x)|\le \Big(\sum_{j\in\mathbb{Z}}|T_{j,m}(f,g)|^r\Big)^\frac{1}{r},
\end{equation*}
it follows from H\"older inequality and Proposition \ref{Tjmb} that
\begin{align}
	\big\|T_{j(x),m}(f,g)(x)\big\|_{L^r(dx)}&\le \Big(\sum_{j\in\mathbb{Z}}\|T_{j,m}(f,g)\|_r^r\Big)^\frac{1}{r}\nonumber\\
	&\le (1+m^{1-\frac{1}{r}})2^{-\frac{m}{20r}} \Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^r\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^r\Big)^\frac{1}{r}.\label{supTjm}
\end{align}

Notice that for $r\in [1,\infty)$ and for any $f, \phi\in\mathcal{S}(\mathbb{R})$, we have
\begin{align*}
\Big(\sum_{j\in\mathbb{Z}}\|f*\phi_j\|_{2r}^{2r}\Big)^\frac{1}{2r}&\le \Bigg(\int_\mathbb{R} \sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^{2r}dx\Bigg)^\frac{1}{2r}\\
&\le \Bigg(\int_\mathbb{R} \Bigg(\sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^2\Bigg)^rdx\Bigg)^\frac{1}{2r} = \Bigg(\int_\mathbb{R} \Bigg\{\bigg(\sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^2\bigg)^\frac{1}{2}\Bigg\}^{2r}dx\Bigg)^\frac{1}{2r}\\
&=\Bigg\|\bigg(\sum_{j\in\mathbb{Z}}|f*\phi_j(x)|^2\bigg)^\frac{1}{2}\Bigg\|_{2r}
\lesssim \|f\|_{2r},
\end{align*}
here for the last relation we used standard Littlewood-Paley theory.

By Cauchy Schwartz, the hypothesis on $\gamma\in \mathcal{NF}$ and the result above, we obtain
\begin{align}
\Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^r\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^r\Big)^\frac{1}{r}&\le \Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^{2r}\Big)^\frac{1}{2r}\Big(\sum_{j\in\mathbb{Z}}\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^{2r}\Big)^\frac{1}{2r} \nonumber\\
&\le_{\gamma,r} \|f\|_{2r}\|g\|_{2r}.\label{fg2r}
\end{align}

Inserting \eqref{fg2r} in \eqref{supTjm} we get
\begin{equation}
\big\|T_{j(x),m}(f,g)(x)\big\|_{L^r(dx)}\le_{\gamma,r} (1+m^{1-\frac{1}{r}})2^{-\frac{m}{20r}}\|f\|_{2r}\|g\|_{2r},
\end{equation}
as desired.
\end{proof}

\begin{observation}
In order to prove our main Theorem \ref{high_frequency_diagonal theorem} in the interior of $\triangle ABC$ it is in fact not necessary to pursue the boundedness of our operator along the edge $(CD)$. Indeed, one could apply interpolation between the bounds corresponding to the edges $(AB)$ and $(AC)$ instead, with the latter discussed in the next section. However, we wanted to offer a less expected but more interesting alternative approach to the trivial bounds one gets along the segment $(AC)$. This is especially useful in situations in which one deals with similar type operators but for which one does not have a good control on the edges $(BC)$ and $(AC)$.
\end{observation}

Bounds on the edge $(AC]$: $1< p\le \infty$, $r=p$ and $q=\infty$
$\newline$

From the definition \eqref{definition} of $M_\Gamma$ it is trivial to notice that for all $x\in\mathbb{R}$,
\begin{align}
|M_\Gamma(f,g)(x)|&\le \|g\|_\infty\, \sup_{\varepsilon>0}\frac{1}{2\varepsilon}\int_{-\varepsilon}^\varepsilon |f(x-t)|dt\nonumber\\
&\le \|g\|_\infty\, Mf(x).\label{1inf1}
\end{align}
Hence, applying the classical results on the Hardy-Littlewood maximal operator we get
\begin{theorem}\label{ginfty}
	For any $1<p\le \infty$, one has
	\begin{equation}
	\|M_\Gamma(f,g)\|_{L^p}\lesssim_p \|f\|_p\,\|g\|_\infty.
	\end{equation}
\end{theorem}
$\smallskip$

Bounds on the edge $(BC]$: $1< q\le \infty$, $r=q$ and $p=\infty$
$\newline$

Our goal in this section is to prove the following:
\begin{theorem}\label{finfty}
	For any $1<q\le \infty$, one has
	\begin{equation}
	\|M_\Gamma(f,g)\|_{L^q}\lesssim_{\gamma,q} \|f\|_\infty\,\|g\|_q.
	\end{equation}
\end{theorem}

From \eqref{discretizationc}, recalling that $\gamma\in\mathcal{NF}$ and our choice of $j_0$ in \eqref{threshold} - \eqref{threshold1}, we notice that for all $x\in\mathbb{R}$,
\begin{align}
|M_\Gamma(f,g)(x)|&\le \|f\|_\infty\,M_\gamma\, g(x)\label{ginf}.
\end{align}
where here
\begin{equation}
M_\gamma\, g(x):=\sup\limits_{{j\in\mathbb{Z}}\atop{|j|>j_0}}\frac{1}{2^{j+1}}\int\limits_{2^j\le|t|\le2^{j+1}}  |g(x+\gamma(t))|dt\,.
\end{equation}


Thus, Theorem \ref{finfty} follows from the result below
\begin{theorem}\label{Mgamma}
	For any $1<q\le \infty$, one has
	\begin{equation}
	\|M_\gamma(g)\|_{L^q}\lesssim_{\gamma,q} \|g\|_q.
	\end{equation}
\end{theorem}

\begin{proof}
From the properties of $\gamma$ and the choice of $j_0$ in \eqref{threshold} - \eqref{threshold1}, it is straightforward to check that for any $k\in \mathbb{Z}$ with $|k|>j_0$  and $t\in[2^k,2^{k+1}]$ one has
\begin{equation}\label{gammak1t}
|\gamma(2^{k})|\approx_{\gamma} 2^{k}|\gamma'(t)|\approx_{\gamma}|\gamma(2^{k+1})|\,.
\end{equation}

From \eqref{threshold1}, we deduce that $\gamma$ is strictly monotone and invertible over each of the intervals
$(-\infty,-2^{j_0})$, $(-2^{-j_0},0)$, $(0,2^{-j_0})$  and $(2^{j_0}, \infty)$. Wlog we consider from now on that our entire discussion takes place relative to $J_0:=(2^{j_0}, \infty)$ and that both $\gamma'$ and $\gamma''$ are strictly positive on $J_0$. Thus, for $k\in\mathbb{Z}$ with $k>j_0$, one has
\begin{align*}
\frac{1}{2^{k+1}}\int_{2^k}^{2^{k+1}}|g(x+\gamma(t))|dt &=\frac{1}{2^{k+1}}\int_{\gamma([2^k,2^{k+1}])}|g(x+u)|\frac{du}{|\gamma'(\gamma^{-1}(u))|}\\
&\le\frac{1}{2^{k+1}|\gamma'(2^k)|}\int_{\gamma(2^k)}^{\gamma(2^{k+1})}|g(x+u)|du\,.
\end{align*}
Appealing now to \eqref{gammak1t}, we deduce
\begin{equation}\label{ks}
\frac{1}{2^{k+1}}\int_{2^k}^{2^{k+1}}|g(x+\gamma(t))|dt \leq\frac{1}{2^{k+1}|\gamma'(2^k)|}\int_{-|\gamma(2^k)|-|\gamma(2^{k+1})|}^{|\gamma(2^k)|+|\gamma(2^{k+1})|}|g(x-u)|du
\lesssim_{\gamma} Mg(x).
\end{equation}

Analogously,
\begin{align*}
\frac{1}{2^{k+1}}\int_{-2^{k+1}}^{-2^k}|g(x+\gamma(t))|dt&\lesssim_{\gamma} Mg(x).
\end{align*}

Therefore
\begin{equation}
\sup_{{j\in\mathbb{Z}}\atop{|j|>j_0}}\,\frac{1}{2^{j+1}}\int\limits_{2^j\le|t|\le2^{j+1}} |g(x+\gamma(t))|dt\lesssim_{\gamma} Mg(x).
\end{equation}
Using now the standard theory on Hardy Littlewood maximal operator we conclude our Theorem \ref{Mgamma}.
\end{proof}


\medskip

We claim that one can get an extension of the above result to the \emph{variable} case, that is

\begin{theorem}\label{smallk20}
 There exists $\epsilon\in(0,1)$ such that, for any $m\in\mathbb{N}$, one has
\begin{equation}\label{l2c1}
 \|T_{j(x),m}(f,g)(x)\|_{L^1(dx)}\lesssim_{\gamma} 2^{-\epsilon m}\|f\|_2\,\|g\|_{2}.

Furthermore, for any $p, q$ and $r$ satisfying \eqref{exponents10} and \eqref{exponents20} we have
\begin{equation}\label{pointwise_maximal_bound}
 \|\mathcal{M}_\Gamma^L(f,g)\|_r\lesssim_{\gamma,p,q}\|f\|_p\|g\|_{q}.
\end{equation}
\end{theorem}

