\Lambda_m^+(f,g,h):=\sum_{j\in\mathbb{N}} \Lambda_{j,m}(f,g,h)\quad \text{ and } \quad \Lambda_m^-(f,g,h):=\sum_{j\in\mathbb{Z}\setminus\mathbb{N}} \Lambda_{j,m}(f,g,h).
\end{equation}
Since our $\Lambda's$ involve absolute values inside the integral expressions, in order to be able to use the techniques in \cite{lie2015triangle}, we will first apply a linearization procedure. Thus, for a suitable sequence of $L^{\infty}-$functions $\{\epsilon_{j,m}\}$ with the property $|\epsilon_{j,m}(x)|=1$ a.e $x\in\mathbb{R}$, we will re-write
\begin{equation}\label{Lambdare}
\Lambda_m^+(f,g,h):=\sum_{j\in\mathbb{N}} \int_{\mathbb{R}} T_{j,m}(f,g)(x)\, \epsilon_{j,m}(x)\,h(x)\,dx,\,
\end{equation}
with the obvious correspondence for $\Lambda_m^-(f,g,h)$.


Deduce now that \eqref{l2cpp} is in fact equivalent with
\begin{equation}\label{l2cppg}
 \left|\Lambda_m^{\pm}(f,g,h)\right|\lesssim_{\gamma,p} m\,\|f\|_p\,\|g\|_{p'}\,\|h\|_{\infty}.
\end{equation}
In what follows we will only focus on the $+$ component since the $-$ component can be treated in a similar fashion.

We will split our discussion in two sub-cases $\newline$

\noindent\textbf{Case 1.} $1<p\leq 2$
$\newline$

With the notations\footnote{We will only recall here that $\phi_{j,p_0}(\eta):= \phi(\frac{\gamma'(2^{-j})\,\eta}{2^j}-p_0)
$ and $\psi_{m,p_0,j}(\xi):= 2^{-\frac{m}{2}}\,e^{- i p_0 R(\frac{\xi}{2^j\,p_0})}\,\phi(\frac{\xi}{2^{m+j}})$ where $j\in\mathbb{N}$ and $p_0\in [2^m,\, 2^{m+1})\cap \mathbb{N}$ with $m\in\mathbb{N}$.} in \cite{lie2015triangle}, following the first part of the argument provided for the proof of Proposition 4.2 in Section 4 of \cite{lie2015triangle}, we have
$$|\ll_{m}^{+}(f,g,h)|\lesssim$$
$$\int_{\mathbb{R}}\left( \sum_{j\in\mathbb{N}}|(f*\check{\phi}_{m+j})(y)|^2\right)^{\frac{1}{2}}\:
\left( \sum_{j\in\mathbb{N}} \left|M\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m} h)*\check{\phi}_{j,p_0})|\right)(y)\right|^2\right)^{\frac{1}{2}}\,dy$$
$$\lesssim \left\| \left( \sum_{j\in\mathbb{N}}|f*\check{\phi}_{m+j}|^2\right)^{\frac{1}{2}}\right\|_{p}\,
\left\|\left( \sum_{j\in\mathbb{N}} \left|M\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|\right)\right|^2\right)^{\frac{1}{2}}\right\|_{p'}$$
$$\lesssim \|f\|_{p}\,\left\|\left( \sum_{j\in\mathbb{N}}\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|\right)^2\right)^{\frac{1}{2}}\right\|_{p'}\:,$$
where for the last relation we used standard Littlewood-Paley theory (for providing bounds on the square function for $f$) and Fefferman-Stein's inequality (\cite{fefferman1971some}) (for the term involving the functions $g$ and $h$).

Using now that
\begin{equation}\label{conv}
((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})(x)=\int_{\mathbb{R}} (\epsilon_{j,m}\, h)(x-\frac{\gamma'(2^{-j})}{2^j}\,y)\,\check{\phi}(y)\,e^{i\,p_0\,y}\,dy\:,
\end{equation}
we deduce that
\begin{equation}\label{L2infcont}
\sum_{p_0=2^m}^{2^{m+1}}|((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|^2\lesssim_{\gamma} \|h\|_{\infty}^2\,.
\end{equation}

Thus, applying Cauchy-Schwarz inequality, we get
\begin{equation}\label{CS}
\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|\right)^2\lesssim_{\gamma} \|h\|_{\infty}^2\,\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})|^2\,,
\end{equation}
from which we deduce that
\begin{equation}\label{L}
|\ll_{m}^{+}(f,g,h)|\lesssim_{\gamma}  \|f\|_{p}\, \|h\|_{\infty}\,\left\|\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|g*\check{\phi}_{j,p_0}|^2\right)^{\frac{1}{2}}\right\|_{p'}\:.
\end{equation}

Finally, since $p'\geq2$, we are allowed to apply Rubio de Francia's inequality (\cite{rubio1985littlewood}):
\begin{equation}\label{RF}
\left\|\left( \sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|g*\check{\phi}_{j,p_0}|^2\right)^{\frac{1}{2}}\right\|_{p'}\lesssim_{\gamma,p'} \|g\|_{p'}\:.
\end{equation}
Putting now together \eqref{CS}, \eqref{L}, \eqref{RF} we conclude that \eqref{l2cppg} holds.
$\newline$


\noindent\textbf{Case 2.} $2<p<\infty$
$\newline$

In this second case, we follow part of the argument inside the proof of Proposition 4.3 in Section 4 of \cite{lie2015triangle}.

Indeed, by applying Cauchy-Schwarz and then H\"older's inequality, we have
\beq\label{key2}
\eeq
$$|\ll_{m}^{+}(f,g,h)|\leq$$
$$\sum_{j\in\mathbb{N}}\int_{\mathbb{R}}
\,\left(\sum_{p_0=2^m}^{2^{m+1}}|(f*\check{\phi}_{m+j}*\check{\psi}_{m,p_0,j})(x)|^2\right)^{\frac{1}{2}}\times
\left(\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})(x)\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})(x)|^{2}\right)^{\frac{1}{2}}\,dx$$
$$\leq\left\|\,\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|(f*\check{\phi}_{m+j}*\check{\psi}_{m,p_0,j})|^2\right)^{\frac{1}{2}}\right\|_{p}
\left\|\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})|^{2}\right)^{\frac{1}{2}}\right\|_{p'}\:.$$

Now the content of Proposition 4.4 in \cite{lie2015triangle} is the statement that for $p\geq2$ one has
\begin{equation}\label{Cf}
\left\|\,\left(\sum_{j\in\mathbb{N}}\sum_{p_0=2^m}^{2^{m+1}}|f*\check{\phi}_{m+j}*\check{\psi}_{m,p_0,j}|^2\right)^{\frac{1}{2}}\right\|_{p}\lesssim_{\gamma,p} m^{\frac{2}{p'}-1}\, \|f\|_{p}\;,
\end{equation}
while from the Lemma 4.9 in \cite{lie2015triangle} we deduce that
\begin{equation}\label{claim}
\sum_{p_0=2^m}^{2^{m+1}}|(g*\check{\phi}_{j,p_0})(x)\,((\epsilon_{j,m}\, h)*\check{\phi}_{j,p_0})(x)|^{2}\lesssim_{\gamma} \|h\|_{\infty}^2\, M(g*\check{\phi}_{\gamma,m,j})^2(x)\:,
\end{equation}
where here we recall that $\phi_{\gamma,m,j}(\eta):=\phi(\frac{\gamma'(2^{-j})}{2^{j+m}}\,\eta)\;.$

Inserting \eqref{Cf} and \eqref{claim} in \eqref{key2}, we conclude that

\beq\label{key3}
\eeq
$$|\ll_{m}^{+}(f,g,h)|\leq_{\gamma,p}  m^{\frac{2}{p'}-1}\, \|f\|_{p}\,\|h\|_{\infty}\,
\left\|\left(\sum_{j\in\mathbb{N}} M(g*\check{\phi}_{\gamma,m,j})^2\right)^{\frac{1}{2}}\right\|_{p'}$$
$$\lesssim_{p} m^{\frac{2}{p'}-1}\, \|f\|_{p}\,\|h\|_{\infty}\,
\left\|\left(\sum_{j\in\mathbb{N}} (g*\check{\phi}_{\gamma,m,j})^2\right)^{\frac{1}{2}}\right\|_{p'}\lesssim_{\gamma,p} m^{\frac{2}{p'}-1}\, \|f\|_{p}\,\|g\|_{p'}\,\|h\|_{\infty}\,,$$
where we made use again of the Fefferman-Stein's inequality (\cite{fefferman1971some}) (for the second inequality) and standard Littlewood-Paley theory (for the third inequality).

\begin{observation}
Let $\mathcal{P}_d$ be the class of all real polynomials of degree $d$ with no linear and constant terms. In \cite[Section 3]{liXiao2016uniform}, the authors show that for any $d\in\mathbb{N}$, $d\ge2$, there exists a polynomial
$P_d\in\mathcal{P}_d$ such that for $\Gamma=(t,P(t))$ one has that $M_\Gamma$ is unbounded whenever $p, q, r$ obey \eqref{exponents10} with $1<p, q<\infty$ and $r<\frac{d-1}{d}$.

However, for any $d\in\mathbb{N}$, $d\ge2$ we have that $\mathcal{P}_d\subset\mathcal{NF}$. Thus, in order for \eqref{exponents10} and \eqref{exponents20} to hold for any $\gamma\in\mathcal{NF}$ we must have $r\ge 1$, hence the claimed optimality of the range in our theorem above.
\end{observation}

\begin{proof}
Fix $m,n \in\mathbb{Z}_-$. From the definition of $\phi$ we have that $\big|\frac{\xi}{2^{j(x)}}\big|, \big|\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\big|\lesssim 1$, and by property (3)  as part of the definition of $\mathcal{NF}$ in \cite{lie2015boundedness}, we have
\[
\sup\limits_{t\in\supp\underline{\rho}}\Big|\eta\gamma\Big(\frac{t}{2^{j(x)}} \Big)\Big|<C_\gamma,
\]
where $C_\gamma$ is a positive constant that is allowed to change from line to line.

Recalling now \eqref{M_multiplierr} - \eqref{mjmn}, we develop the phase in \eqref{phmultiplier} in a Taylor series
\begin{align}
 m_{j(x),m,n}(\xi,\eta)&=\Bigg(\int_\mathbb{R} \sum_{k\in\mathbb{N}} \frac{(-i\frac{\xi}{2^{j(x)}}t)^k}{k!}\sum_{l\in\mathbb{N}}\frac{(i\eta\gamma(\frac{t}{2^{j(x)}}))^l}{l\,!}\underline{\rho}(t)dt\Bigg)\phi\Big(\frac{\xi}{2^{m+j(x)}} \Big)\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big)\nonumber\\

&=\sum_{k,l\ge0}\frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l}
\Big(\frac{\xi}{2^{j(x)}}\Big)^k\phi\Big(\frac{\xi}{2^{m+j(x)}}\Big) \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big)^l\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big),\label{taylor-series}
\end{align}
where
\[
 C_{k,l}=C_{j(x),k,l}:=\int_\mathbb{R} t^k\Big(\frac{\gamma(2^{-j(x)}t)}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)^l \underline{\rho}(t)dt.
\]
Since
\begin{equation}\label{constcont}
 |C_{k,l}|\lesssim C_\gamma^{k+l}
\end{equation}
uniformly in $x$, the sum \eqref{taylor-series} converges absolutely.

Set now
\begin{equation}\label{psi}
\psi(x):=\sum_{m<0}\phi(\frac{x}{2^m})\,,
\end{equation}
and notice that $\psi\in\mathcal{S}(\mathbb{R})$ since $\psi=1-\sum_{m\ge0}\phi_m.$

Inserting \eqref{taylor-series} in \eqref{low_freq} and recalling \eqref{notation21}, we have
\begin{align}
 m^L_{j(x)}(\xi,\eta)&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \Big(\frac{\xi}{2^{j(x)}}\Big)^k\psi\Big(\frac{\xi}{2^{j(x)}}\Big) \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big)^l
\psi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big),\\
&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \,\tilde\psi_k\Big(\frac{\xi}{2^{j(x)}}\Big) \tilde\psi_l\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big).\label{lowTaylor}
\end{align}



Thus, putting together \eqref{lowTaylor} and \eqref{operator_low_freq} and recalling \eqref{notation22}, we have
\begin{align}
\mathcal{M}_\Gamma^L(f,g)(x)&=\sum_{k,l\ge0} \frac{(-1)^k i^{k+l}}{k!\,l\,!}C_{k,l} \Big(\int_\mathbb{R} \hat{f}(\xi)\tilde\psi_k\Big(\frac{\xi}{2^{j(x)}}\Big)e^{i\xi x}d\xi\Big) \Big(\int_\mathbb{R} \hat{g}(\eta)\tilde\psi_l\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{j(x)}}\Big) e^{i\eta x}d\eta\Big)\nonumber\\
&\approx\sum_{k,l\ge0} \frac{(-1)^k }{k!\,l\,!}C_{k,l} \Big(f*\Big\{\frac{1}{2^{-j(x)}}\check{\psi}^{(k)}\Big(\frac{\cdot}{2^{-j(x)}}\Big)\Big\}\Big)(x)\label{low_frequency}\\
&\hspace{2cm}\times \Big(g*\Big\{\frac{1}{2^{-j(x)}\gamma'(2^{-j(x)})}\check{\psi}^{(l)} \Big(\frac{\cdot}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)\Big\}\Big)(x).\nonumber
\end{align}

We can construct the function $\phi$ such that for every $k\in\mathbb{N}$, the function $\check{\psi}^{(k)}$ has an integrable radially decreasing majorant $\Phi_k$ with $\|\Phi_k\|_1\lesssim C^k$ for some constant $C>0$. Thus, using a classical result in \cite{stein1993harmonic}, one has
\begin{align}
\Big|\Big(f*\Big\{\frac{1}{2^{-j(x)}}\check{\psi}^{(k)}\Big(\frac{\cdot}{2^{-j(x)}}\Big)\Big\}\Big)(x)\Big|&\le \sup_{t>0} \Big|\Big(f*\Big\{\frac{1}{t}\check{\psi}^{(k)}\Big(\frac{\cdot}{t}\Big)\Big\}\Big)(x)\Big|\nonumber\\
&\le \|\Phi_k\|_1 Mf(x)\nonumber\\
&\lesssim C^k Mf(x).\label{Mf}
\end{align}

Analogously,
\begin{equation}\label{Mg}
\Big|\Big(g*\Big\{\frac{1}{2^{-j(x)}\gamma'(2^{-j(x)})}\check{\psi}^{(l)} \Big(\frac{\cdot}{2^{-j(x)}\gamma'(2^{-j(x)})}\Big)\Big\}\Big)(x)\Big|\lesssim C^l Mg(x).
\end{equation}
Putting together \eqref{low_frequency}, \eqref{Mf} and \eqref{Mg} we have
\begin{align*}
|\mathcal{M}_\Gamma^L(f,g)(x)|&\lesssim \sum\limits_{k,l\ge0}\frac{1}{k!\,l\,!}|C_{k,l}|C^{k+l}Mf(x)Mg(x)\\
&\lesssim Mf(x)Mg(x)\sum\limits_{k,l\ge0}\frac{1}{k!\,l\,!}C_\gamma^{k+l} C^{k+l}\\
&\lesssim_\gamma Mf(x)Mg(x),\numberthis\label{pointwise_result}
\end{align*}
where here we used \eqref{constcont}.

Therefore, \eqref{pointwise_maximal} holds.

Taking now $p,\, q,\, r$ satisfying \eqref{exponents10} and \eqref{exponents20}, H\"older’s inequality and the standard $L^p$ strong type estimate for the classical Hardy-Littlewood maximal function imply
 \begin{align*}
\|\mathcal{M}_\Gamma^L(f,g)\|_r&\lesssim_\gamma\|Mf Mg\|_r\lesssim_{p,q} \|Mf\|_p\|Mg\|_q\lesssim_{p,q} \|f\|_p \|g\|_q,
 \end{align*}
which concludes our proof.
\end{proof}

With these we are now ready to present

\begin{proof}[Proof of Theorem \ref{far_theorem}]

Fix a pair $(m,n)\in\mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)$. As in the proof of \cite[Claim 1]{lie2015boundedness}, integrating by parts, we write
\[
 m_{j(x),m,n}=A_{j(x),m,n}(\xi,\eta)+B_{j(x),m,n}(\xi,\eta),
\]
where
\begin{equation}
 A_{j(x),m,n}(\xi,\eta):=\Big(\int_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t} e^{i\eta\gamma(\frac{t}{2^{j(x)}})} \frac{i\
\underline{\rho}'(t)}{-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}dt\Big)
\phi\Big(\frac{\xi}{2^{m+j(x)}} \Big) \phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big),
\end{equation}
and
\begin{equation}
 B_{j(x),m,n}(\xi,\eta):= \Big(\int\limits_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t}e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)}
\frac{-i\frac{\eta}{2^{2j(x)}}\gamma''\big(\frac{t}{2^{j(x)}}\big)} {\Big({-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}\Big)^2} \underline{\rho}(t)dt\Big)
\phi\Big(\frac{\xi}{2^{m+j(x)}}\Big)\phi\Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big).
\end{equation}



\item \textsf{Case 1}: $m-n\ge C_\gamma>>1$
$\newline$

By (3) in the definition of $\mathcal{NF}$, we have that
\[
\tfrac{1}{-\tfrac{\xi}{2^{j(x)}}+\tfrac{\eta}{2^{j(x)}}\gamma'\big(\frac{t}{2^{j(x)}}\big)}=-\tfrac{1}{2^m}\frac{1}{\frac{\xi}{2^{m+j(x)}}} \sum_{l\in\mathbb{N}} \tfrac{1}{2^{l(m-n)}}\Bigg(\frac{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}{\frac
{\xi}{2^{m+j(x)}}}\Bigg)^l (Q'(t)+Q'_{j(x)}(t))^l.
\]
Set
\[
 A_{j(x),m,n}=\sum_{l\in\mathbb{N}} A_{j(x),m,n,l},
\]
with
\begin{align*}
 A_{j(x),m,n,l}(\xi,\eta)&=-\frac{1}{2^m}\frac{1}{2^{l(m-n)}} \left(\int_\mathbb{R} e^{-i\frac{\xi}{2^{j(x)}}t} e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)} i\,\underline{\rho}'(t) (Q'(t)+Q_{j(x)}(t))^l dt\right)\\
&\hspace{2.5cm}\times
\tilde{\phi}_{-l-1}\Big(\frac{\xi}{2^{m+j(x)}}\Big)\tilde{\phi}_{l} \Big(\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}\Big)
\end{align*}
where here $\tilde{\phi}_{l}$, $l\in\mathbb{Z}$, is smooth, compactly supported away from the origin, and obeying
\[
\|\tilde{\phi}_{l}\|_{C^\beta}\lesssim\beta!\,(|l|+\b)^{\b}\,
C^{|l|+\b}
\]
for $\b\in\mathbb{N}$ and some fixed $C>0$.

We recall now the fact that, from the properties of $\gamma\in\mathcal{NF}$ one has that $\|Q_j\|_{C^N}\le a_j$ with $a_j\to 0$ as
$j\to\infty$ and thus, since $|j(x)|\geq j_0$, one can choose $j_0\in\mathbb{N}$ large enough so that $\|Q_{j(x)}\|_{C^N}\leq \|Q\|_{C^N}\:\:\textrm{a.e.}\:x\in\mathbb{R}$.

 Defining the operator $\Lambda^A$ as
\[
\Lambda^A_{m,n,l}(f,g)(x):=\int_\mathbb{R}\int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta) A_{j(x),m,n,l}(\xi,\eta)e^{i\xi x}e^{i\eta x}d\xi d \eta,
\]
we have
\begin{align}
|\Lambda^A_{m,n,l}(f,g)(x)|&=\Big|\frac{1}{2^m}\frac{1}{2^{l(m-n)}} \int_\mathbb{R} (f*\check{\tilde{\phi}}_{-l-1,m+j(x)})\big(x-\frac{2^mt}{2^{m+j(x)}}\big)\label{sqv}\\
&\hspace{.1cm}\times \big(g*\big\{\tilde{\phi}_l\big(\tfrac{2^{-j(x)}\gamma'(2^{-j(x)})}{2^n}\,\cdot\big)\big\} \check{\phantom{1}}\big)\big(x+\gamma(2^{-j(x)}t)\big) \,\underline{\rho}'(t)\,(Q'(t)+Q'_{j(x)}(t))^l\, dt\Big|\nonumber\\
&\lesssim \frac{1}{2^m}\Big(\frac{2\|Q'\|_\infty}{2^{m-n}}\Big)^l \int\limits_{\{t\in\mathbb{R}:\frac{1}{4} <|t|<1 \}}
\sup_{j\in\mathbb{Z}}\Big|(f*\check{\tilde{\phi}}_{-l-1,j})\big(x-\frac{2^mt}{2^j}\big)\Big| \nonumber\\
&\hspace{.5cm}\times
\sup_{j\in\mathbb{Z}}\Big|\big(g*\big\{\frac{1}{\tfrac{2^{-j}\gamma'(2^{-j})}{2^n}} \check{\tilde{\phi}}_l (\frac{\cdot}{\tfrac{2^{-j}\gamma'(2^{-j})}{2^n}})\big\}\big) (x+\gamma(2^{-j}t))\,\Big|\,dt\nonumber\:.
\end{align}
Once at this point one can proceed in two ways:
\begin{itemize}
\item the simplest route is to apply the estimate
\begin{equation}\label{mv}
|\Lambda^A_{m,n,l}(f,g)(x)|\lesssim \frac{1}{2^m}\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l \int\limits_{\{\frac{1}{4} <|t|<1 \}} M^{(2^m t)}f(x)\,M^{(2^n)}_{\gamma_t} g(x)\,dt\,.
\end{equation}
\item alternatively, one can appeal to a shifted square function argument, and write
\begin{equation}\label{sv}
|\Lambda^A_{m,n,l}(f,g)(x)|\lesssim \frac{1}{2^m}\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l \left(\int\limits_{\{\frac{1}{4} <|t|<1 \}} S_{2^mt}^{\tilde{\phi}_{-l-1}}f(x)\,S_{n,\gamma_t}^{\tilde{\phi}_l}g(x)\,dt\right)\,.
\end{equation}
\end{itemize}




Let $\Lambda^A_{m,n}:=\sum_{l\in\mathbb{N}} \Lambda^A_{m,n,l}$. Using now Fubini, H\"older, Lemma \ref{shifted_max_funct} and \eqref{mv} (or alternatively, Lemma \ref{shifted_square_funct} and \eqref{sv}), one deduces
\begin{equation}\label{A1}
\|\Lambda^A_{m,n}(f,g)\|_r\lesssim_{\gamma,p,q}\frac{1}{2^m}(m_++10)(n_{+}+10)\,\|f\|_p\,\|g\|_q\:.
\end{equation}



Similarly, one gets the analogues of \eqref{A1} for the multiplier $B_{j,m,n}$, where in this latter case one uses that
$\frac{1}{2^{2j}}\gamma''(2^{-j}t)=2^{-j}\gamma'(2^{-j})(Q''(t)+Q_j''(t))\,.$
$\newline$


\item \textsf{Case 2}: $n-m>C_\gamma>>1$
$\newline$

As we did in Case 1, we write
\[
\frac{1}{-\frac{\xi}{2^{j(x)}}+\frac{\eta}{2^{j(x)}}
	\gamma'(\frac{t}{2^{j(x)}})}
=\frac{1}{2^{n}}\frac{1}{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}
\sum_{l\in\mathbb{N}}\frac{1}{2^{l(n-m)}} \Bigg(\frac{\frac{\xi}{2^{m+j(x)}}}
{\frac{\gamma'(2^{-j(x)})\eta}{2^{n+j(x)}}}\Bigg)^l\frac{1}{(Q'(t)+Q'_{j(x)}
	(t))^{l+1}}.
\]
Write
\[
\tilde{A}_{j(x),m,n}=\sum_{l\in\mathbb{N}}\tilde{A}_{j(x),m,n,l},
\]
where
\begin{align*}
\tilde{A}_{j(x),m,n,l}(\xi,\eta)&=\frac{1}{2^{n}}\frac{1}{2^{l(n-m)}}
\left(\int_\mathbb{R}
e^{-i\frac{\xi}{2^{j(x)}}t}e^{i\eta\gamma\big(\frac{t}{2^{j(x)}}\big)}i
\frac{\underline{\rho}'(t)}{(Q'(t)+Q'_{j(x)}(t))^{l+1}}dt\right) \\
&\hspace{2cm}\times
\tilde{\phi}_{l}\left(\frac{\xi}{2^{m+j(x)}}\right)\,\tilde{\phi}_{-l-1}\left(\frac{
	\gamma'(2^{-j(x)})\,\eta}{2^{n+j(x)}}\right).
\end{align*}

Letting $\Lambda^{\tilde{A}}_{m,n,l}$ be the operator with symbol
$\tilde{A}_{j(\cdot),m,n,l}$ one proceeds as before in order to get
\begin{equation*}
|\Lambda^{\tilde{A}}_{m,n,l}(f,g)(x)|\lesssim
\frac{1}{2^n}\,\Big(\frac{C_{\gamma}}{2^{m-n}}\Big)^l\,\left(\int\limits_{\{\frac{1}{4} <|t|<1 \}} M^{(2^m t)}f(x)\,M^{(2^n)}_{\gamma_t} g(x)\,dt\right) \,,
\end{equation*}
and respectively
\begin{equation}\label{A2}
\|\Lambda^{\tilde{A}}_{m,n}(f,g)\|_r\lesssim_{\gamma,p,q} \frac{1}{2^n}(m_++10)\,(n_{+}+10)\,
\|f\|_p\,\|g\|_{q}.
\end{equation}
Again, a similar reasoning applies to the multiplier $\tilde{B}_{j(\cdot),m,n}$.

Putting together all of the above, one concludes
\begin{align*}
\|M_\Gamma^{H\not\Delta}(f,g)\|_r &\lesssim_{\gamma,p,q}
\sum_{\substack{(m,n)\in \mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)\\ m-n\geq C_{\gamma}}}
\frac{1}{2^m}(m_++10)\,(n_{+}+10)\,\|f\|_p\,\|g\|_q\\
&\hspace{1cm} +
\sum_{\substack{(m,n)\in \mathbb{Z}^2\setminus((\mathbb{Z}_-)^2\cup\Delta)\\ n-m\geq C_{\gamma}}}
\frac{1}{2^n}(m_++10)\,(n_{+}+10)\,\|f\|_p\,\|g\|_q\\
&\lesssim_{\gamma,p,q} \|f\|_p\,\|g\|_q.
\end{align*}
\end{proof}

In this subsection we will describe the strategy of reducing our Theorem \ref{high_frequency_diagonal theorem} to two intermediate results.

We start by noticing that in \eqref{high-close} it is enough to only consider the case $m=n.$ Also, wlog we assume that our $t$-integration encoded in the expression of $m_{j(x)}^{H\Delta}$ is performed over $\mathbb{R}_+$.

\begin{observation}\label{identif} Recalling Remark 2 in Section \ref{MIR}, since the mean zero condition in \eqref{mzh} plays no role in the regions where the phase of the multiplier is highly oscillatory, we are justified from now on to identify our operators $T_{j,m}$ and $B_{j,m}$ introduced below with the corresponding ones defined in \cite{lie2015boundedness}. Consequently, one can transfer with no modifications the theorems regarding $T_{j,m}$ and $B_{j,m}$ in \cite{lie2015boundedness} to our current setting.
\end{observation}

Using now the notation from \cite[Section 3]{lie2015triangle} and after some elaborate technicalities, one can prove that the study of the operator with multiplier $m_{j(x)}^{H\Delta}$ can be reduced to the study of the bilinear operator $T(f,g)$ defined by
\begin{equation}\label{T}
 T(f,g)(x):=\sum_{m\in\mathbb{N}}T_{j(x),m}(f,g)(x)\,.
\end{equation}
Here, for each $j\in\mathbb{Z}$ and $m\in\mathbb{N}$, we define
\begin{equation}\label{Tjm}
T_{j,m}(f,g)(x):=\int_\mathbb{R}\int_\mathbb{R}\hat{f}(\xi)\hat{g}(\eta)v_{j,m}(\xi,\eta)e^{i\xi x}e^{i\eta x} d\xi d\eta
\end{equation}
and
\begin{equation}\label{vjm}
v_{j,m}(\xi,\eta):=2^{-\frac{m}{2}}e^{i\,\varphi_{\xi,\eta}(t_c)} \zeta\Bigg(\frac{\gamma'(2^{-j})\eta}{2^{m+j}},
\frac{\frac{\xi}{2^{m+j}}}{\frac{\gamma'(2^{-j})\eta}{2^{m+j}}}\Bigg) \phi\Big(\frac{\xi}{2^{m+j}}\Big) \phi\Big(\frac{\gamma(2^{-j})\eta}{2^{m+j}}\Big)
\end{equation}
where we have
\begin{itemize}
 \item the phase of the multiplier - recall \eqref{phmultiplier} - is defined as
 \begin{equation}
\varphi_{\xi,\eta}(t):=-\frac{\xi}{2^j}t+\eta\gamma\big(\frac{t}{2^j}\big).
 \end{equation}
 \item For $\xi,\eta$ fixed, $\varphi_{\xi,\eta}$ has a unique critical point $t_c=t_c(j,\xi,\eta) \in [2^{-k(\gamma)},2^{k(\gamma)}]$, where $k(\gamma)\in\mathbb{N}$ depends only on $\gamma$.
 \item $\zeta:[\frac{1}{10},10]\times[2^{-k(\gamma)},2^{k(\gamma)}]\to\mathbb{R}$ satisfies $\|\zeta\|_{N-3}\lesssim  1$ for some $N\ge7$.\footnote{The regularity index $N$ here can be lowered but we will not detail this fact here.}
\end{itemize}

Also, from the properties of the class $\mathcal{NF}$, wlog we can assume that
\begin{equation}\label{lim}
 \lim\limits_{\substack{t\to0\\ t\not=0}}\gamma'(t)=0\quad \text{ and } \quad \lim\limits_{t\to\infty}\gamma'(t)=\infty.
\end{equation}

Now it turns out that in formulas \eqref{Tjm} and \eqref{vjm} one can replace the function $\zeta$ by $1$. In order to clarify this point and make transparent the parallelism with the reasonings in \cite{lie2015boundedness}, we first need to recall some of the notations that we used in \cite{lie2015boundedness}. Thus, letting $\Psi_\eta(\xi)=-\varphi_{\xi,\eta}(t_c)$, we have




\begin{itemize}
 \item For $j>0$ one sets
\begin{equation}\label{BTtr1}
B_{j,m}(f(\cdot),g(\cdot))(x):=[\gamma'(2^{-j})]^\frac{1}{2}T_{j,m} \Big(f(2^{m+j}\cdot),g\Big(\frac{2^{m+j}}{\gamma'(2^{-j})} \cdot\Big)\Big)\Big(\frac{x\gamma'(2^{-j})}{2^{m+j}}\Big),
\end{equation}
that is
\[
B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i 2^m 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)}\zeta(\eta,\frac{\xi}{\eta})\phi(\xi)\phi(\eta)d\xi d\eta.
\]
 \item For $j\le 0$ one sets
\begin{equation}\label{BTtr2}
B_{j,m}(f(\cdot),g(\cdot))(x):=[\gamma'(2^{-j})]^{-\frac{1}{2}}T_{j,m} \Big(f(2^{m+j}\cdot),g\Big(\frac{2^{m+j}}{\gamma'(2^{-j})} \cdot\Big)\Big)\Big(\frac{x}{2^{m+j}}\Big),
\end{equation}
that is
\[
B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^{-\frac{1}{2}} \int_\mathbb{R} \int_\mathbb{R}
\hat{f}(\xi)\hat{g}(\eta)e^{i(\xi+\frac{\eta}{\gamma'(2^{-j})})x} e^{-i 2^m 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)}
\zeta(\eta,\frac{\xi}{\eta})\phi(\xi)\phi(\eta)d\xi d\eta.
\]
\end{itemize}
In what follows we will assume $j>0$, as the other case $j < 0$ can be treated in a similar way.

From the definition of $\gamma\in\mathcal{NF}$ we define for $x\in\mathbb{R}$
\[
 R(u):=\int_1^u r(s)ds \quad\text\quad R_{j}(u)=\int_1^u r_{j}(s)ds,
\]
then
\[
 2^{j}\Psi_{\frac{\eta}{\gamma'(2^{-j})}}(\xi)=\eta R(\frac{\xi}{\eta})+\eta R_{j}(\frac{\xi}{\eta}).
\]
From the properties of $\gamma\in\mathcal{NF}$ we know that $\lim_{|j|\rightarrow\infty} \|R_j\|_{C^N}=0$. Thus, by properly choosing $j_0\in\mathbb{N}$ in \eqref{threshold} (based on the properties of $\gamma\in\mathcal{NF}$), one can assume wlog that one has the pointwise estimate $|R_j|\leq \frac{1}{C_{\gamma}}|R|$ for some large $C_{\gamma}>>1$. Consequently, $R_j$ behaves as an error term relative to $R$, and thus, for notational simplicity,  we will discard $R_j$ in what follows.


Thus, we have
\begin{equation}\label{bjxm}
B_{j,m}(f,g)(x):=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R}
\int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i 2^m \eta
R(\frac{\xi}{\eta})}\zeta(\eta,\frac{\xi}{\eta}
)\phi(\xi)\phi(\eta)d\xi d\eta.
\end{equation}


With these we are now ready to state the following

\begin{observation}
As in \cite[Section 5]{lie2015boundedness}, one can show that the function
$\zeta$ above can be replaced by the constant function $1$. This brings a series of simplifications especially when dealing later with the situation $p\not=2$. Instead of following the argument in  \cite[Section 5]{lie2015boundedness}, we present here a much simpler approach: the secret lies in changing the perspective and focusing on the function
\[
\varrho(\xi,\eta):=\zeta(\eta,\frac{\xi}{\eta})\,.
\]
Indeed, by doing this, one can perform a double Fourier series development on $\varrho$ and notice that the linear complex exponentials will preserve the curvature of the phase given by $2^m\eta R(\frac{\xi}{\eta})$; in contrast with this, in the original argument focusing on $\zeta(\eta,\frac{\xi}{\eta})$, after the double Fourier series argument one had to work extra in order to deal with expressions of the form $\{\frac{\xi}{\eta}n_2\}_{n_2\in\mathbb{Z}}$.

Returning now to the above definition of $ \varrho$ we notice that $\varrho:[\frac{2^{-k(\gamma)}}{10},10\cdot 2^{k(\gamma)}]
\times[\frac{1}{10},10] \to\mathbb{R}$ satisfies $\|\varrho\|_{C^{N-3}}\lesssim_\gamma
1$. This last property follows from the fact that both $\xi$
and $\eta$ are away from $0$.

We can now assume without loss of generality that $\varrho$ is compactly supported on $[2\pi,4\pi]\times[2\pi,4\pi]$. Regarding now $\varrho$ as a $2\pi$-periodic function on $\mathbb{R}^2$, we represent it as a multiple Fourier series:
\[
\varrho(\xi,\eta)=\sum_{n_1,n_2\in\mathbb{Z}}c_{n_1,n_2}e^{i n_1 \xi}e^{i n_2 \eta}.
\]

From the hypothesis that $\|\varrho\|_{C^{N-3}}\lesssim_\gamma 1$ with $N\geq 7$, we have
\begin{equation}\label{z-coefficients}
|c_{n_1,n_2}|\lesssim_\gamma \frac{1}{(1+|n_1|+|n_2|)^4}.
\end{equation}
Thus, for $j>0$, it follows that
\begin{equation}\label{B-Fourier}
B_{j,m}(f,g)(x)=\sum_{n_1,n_2\in\mathbb{Z}}c_{n_1,n_2}B_{j,m}^{n_1,n_2}(f,g)(x)
\end{equation}
with
\begin{equation}\label{BFourier1}
B_{j,m}^{n_1,n_2}(f,g)(x):=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2}
\int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x}e^{-i
	2^m \eta R(\frac{\xi}{\eta})}e^{i\xi n_1}e^{i\eta n_2}\phi(\xi)\phi(\eta)d\xi d\eta.
\end{equation}
At this point we make the following simple observation: $\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}$ for any $n_1,\,n_2\in \mathbb{Z}$ since
the factors $e^{i\xi n_1}$ and $e^{i\eta n_2}$ can be absorbed into the functions $\hat f$ and $\hat g$ in \eqref{BFourier1} without changing their corresponding $L^2$-norms.

Consequently, since \eqref{z-coefficients} implies the absolute convergence of the sum $$\sum_{n_1,n_2}|c_{n_1,n_2}|\,\|B_{j,m}^{n_1,n_2}\|_{L^2\times L^2 \to L^1}=\|B_{j,m}^{0,0}\|_{L^2\times L^2 \to L^1}\,\sum_{n_1,n_2}|c_{n_1,n_2}|\,,$$
one realizes that the boundedness of each of $T_{j,m}$ can be thought as equivalent with the corresponding boundedness of $B_{j,m}^{0,0}$. Therefore, for notational simplicity, we redenote $B_{j,m}$ as $B_{j,m}^{0,0}$ and set $T_{j,m}$ as the correspondent operator associated with the newly defined $B_{j,m}$.
\end{observation}

Given the observation above, we will only focus our attention on
\begin{equation}\label{nbjxm}
 B_{j,m}(f,g)(x)=2^{-\frac{m}{2}}[\gamma'(2^{-j})]^\frac{1}{2} \int_\mathbb{R} \int_\mathbb{R} \hat{f}(\xi)\hat{g}(\eta)e^{i(\gamma'(2^{-j})\xi+\eta)x} e^{-i 2^m\eta R(\frac{\xi}{\eta})}\phi(\xi)\phi(\eta)d\xi d\eta\,,
\end{equation}
or equivalently, on the corresponding operator $T_{j,m}$ obtained from $B_{j,m}$ via \eqref{BTtr1} (and \eqref{BTtr2} respectively).

Finally, we record the following key relation:
\begin{equation}\label{bt}
\|B_{j,m}\|_{L^2\times L^2 \to L^1}=\|T_{j,m}\|_{L^2\times L^2 \to L^1}\:.
\end{equation}

